('01d102f3-0e3a-55be-8d97-80b4f5791bff','eb82a76e-37f1-5a93-87a5-f10650c3c6cf',1,'noun','B2','S2','W3',null,'[{"phrase":"expert witness","register":null,"definition_en":"someone with special knowledge about a subject who is asked to give their opinion about something relating to that subject in a court of law","translation":"شخصی با دانش ویژه در مورد موضوعی که از او خواسته می شود در مورد موضوعی در یک دادگاه حقوقی نظر خود را بیان کند","example":"He appeared as an expert witness before several government inquiries.","example_translation":"او به عنوان شاهد کارشناس در برابر چندین تحقیق دولتی حاضر شد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001653934.mp3"},{"phrase":"be witness to something","register":"formal","definition_en":"to be present when something happens, and watch it happening","translation":"زمانی که اتفاقی می افتد حضور داشته باشید و آن را تماشا کنید","example":"We were witness to the worst excesses of the military.","example_translation":"ما شاهد بدترین افراط و تفریط های نظامی بودیم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000494579.mp3"}]'::jsonb),
('cb1d48d5-fff1-5825-9972-532f67ca3e94','eb82a76e-37f1-5a93-87a5-f10650c3c6cf',2,'verb','B2',null,null,null,'[{"phrase":"witness something","register":null,"definition_en":"used to introduce an example that proves something you have just mentioned","translation":"برای معرفی مثالی استفاده می شود که چیزی را که شما ذکر کردید را ثابت می کند","example":"Bad economic times can result in political dictatorships. Witness Germany in the 1930s.","example_translation":"شرایط بد اقتصادی می تواند منجر به دیکتاتوری سیاسی شود. شاهد آلمان در دهه 1930.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001626862.mp3"}]'::jsonb),
('a1f4490c-10eb-5c18-96ae-a1a80f6e9a52','dd9c5a0f-d6c0-52a6-b42c-f636a57220cc',1,'adjective','A2','S2','W2','[ only before noun ]','[{"phrase":"working day","register":null,"definition_en":"a day of the week when most people work. In Britain and the US this is usually Monday to Friday","translation":"روزی از هفته که اکثر مردم کار می کنند. در بریتانیا و ایالات متحده معمولا از دوشنبه تا جمعه است","example":"It will be returned within three working days (= three days, not including weekends or public holidays ) .","example_translation":"ظرف سه روز کاری (= سه روز، بدون احتساب تعطیلات آخر هفته یا تعطیلات رسمی) بازگردانده خواهد شد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001608749.mp3"},{"phrase":"working life","register":null,"definition_en":"the part of your adult life when you have a paid job","translation":"بخشی از زندگی بزرگسالی شما زمانی که شغلی با درآمد دارید","example":"He spent all his working life in a factory.","example_translation":"او تمام عمر کاری خود را در یک کارخانه گذراند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001608758.mp3"},{"phrase":"working relationship","register":null,"definition_en":"the way that people work together","translation":"روشی که مردم با هم کار می کنند","example":"They want to establish a better working relationship between medical and nursing staff.","example_translation":"آنها می خواهند رابطه کاری بهتری بین کادر پزشکی و پرستاری برقرار کنند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001608770.mp3"},{"phrase":"a working knowledge of something","register":null,"definition_en":"enough knowledge of a system, subject, language etc to be able to use it or to do a particular job","translation":"دانش کافی از یک سیستم، موضوع، زبان و غیره برای استفاده از آن یا انجام یک کار خاص","example":"A good working knowledge of the building regulations is necessary for the job.","example_translation":"دانش کاری خوب از مقررات ساختمان برای این کار ضروری است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001608774.mp3"},{"phrase":"working clothes","register":null,"definition_en":"clothes which you wear for work or are designed for people to work in","translation":"لباس هایی که برای کار می پوشید یا برای افراد طراحی شده اند تا در آن کار کنند","example":"","example_translation":"","example_audio_url":""},{"phrase":"working model","register":null,"definition_en":"a model that has parts that move","translation":"مدلی که دارای قطعاتی است که حرکت می کنند","example":"","example_translation":"","example_audio_url":""},{"phrase":"working parts","register":null,"definition_en":"the parts of a machine that move","translation":"قطعات یک ماشین که حرکت می کنند","example":"","example_translation":"","example_audio_url":""},{"phrase":"working majority","register":null,"definition_en":"enough support in parliament for a government to continue making laws and ruling a country","translation":"حمایت کافی در پارلمان برای ادامه قانونگذاری و اداره یک کشور توسط یک دولت","example":"","example_translation":"","example_audio_url":""},{"phrase":"working memory","register":"technical","definition_en":"the part of a person’s or computer’s memory which stores information about the thing being worked on now","translation":"بخشی از حافظه شخص یا رایانه که اطلاعات مربوط به چیزی را که اکنون روی آن کار می شود ذخیره می کند","example":"","example_translation":"","example_audio_url":""}]'::jsonb),
('cdeb8a22-9944-5689-8292-cf029cd8a876','dd9c5a0f-d6c0-52a6-b42c-f636a57220cc',2,'noun','A2',null,null,null,'[{"phrase":"the workings","register":null,"definition_en":"the way something such as a system, piece of equipment , or organization works","translation":"روش کار چیزی مانند یک سیستم، قطعه تجهیزات یا سازمان","example":"his knowledge of the inner workings of the department","example_translation":"دانش او در مورد عملکرد داخلی بخش","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000499415.mp3"}]'::jsonb),
('3d3a173e-88ea-505c-bd0e-8bc11fd8900d','42242b7b-fd95-5cd9-a7f0-72369dbf3354',1,'adjective','A2','S2','W3',null,'[{"phrase":"you had me worried","register":"spoken","definition_en":"used to say that someone made you feel anxious because you did not properly understand what they said, or did not realize that it was a joke","translation":"می‌گفت کسی به خاطر اینکه درست متوجه حرف‌های او نشده‌اید یا متوجه نشده‌اید که این یک شوخی است، شما را مضطرب کرده است.","example":"You had me worried there for a minute!","example_translation":"من را برای یک دقیقه نگران کردی!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000500429.mp3"},{"phrase":"the worried well","register":null,"definition_en":"healthy people who are worried that they might be ill or become ill","translation":"افراد سالمی که نگران این هستند که ممکن است بیمار شوند یا بیمار شوند","example":"Health tests for the worried well should be strictly regulated.","example_translation":"آزمایشات بهداشتی برای چاه نگران باید به شدت تنظیم شود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/ld5_upd03_021.mp3"}]'::jsonb),
