('43dfe822-e7fb-53fd-a54f-94065eaa962c','eba1a531-7447-546b-a8d0-408c087d9019',1,'pronoun','A1','S1','W1',null,'[{"phrase":"anything but","register":null,"definition_en":"used to emphasize that someone or something does not have a particular quality","translation":"برای تاکید بر اینکه کسی یا چیزی کیفیت خاصی ندارد استفاده می شود","example":"Maria is anything but stupid!","example_translation":"ماریا چیزی جز احمق است!","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000982988.mp3"},{"phrase":"or anything","register":"spoken","definition_en":"or something that is similar","translation":"یا چیزی مشابه","example":"Would you like a drink or anything?","example_translation":"آیا نوشیدنی می خواهید یا هر چیز دیگری؟","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000983014.mp3"},{"phrase":"anything goes","register":"informal","definition_en":"used to say that anything someone says or does is acceptable","translation":"قبلاً می گفت هر چیزی که کسی بگوید یا انجام دهد قابل قبول است","example":"From what other people were wearing, it looked like anything goes.","example_translation":"از لباسی که افراد دیگر پوشیده بودند، به نظر می رسید که همه چیز از بین می رود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001833897.mp3"},{"phrase":"for anything","register":"informal","definition_en":"if you will not do something for anything, you will definitely not do it","translation":"اگر کاری را برای هیچ کاری انجام ندهید، قطعا آن را انجام نخواهید داد","example":"I wouldn’t go back there for anything.","example_translation":"من برای هیچ چیز به آنجا برنمی گردم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000983019.mp3"},{"phrase":"like anything","register":"informal","definition_en":"if you do something like anything, you do it a lot","translation":"اگر کاری شبیه به هر کاری انجام دهید، آن را زیاد انجام می دهید","example":"We all encouraged him like anything.","example_translation":"همه ما مثل هر چیزی او را تشویق می کردیم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000983024.mp3"},{"phrase":"anything you say","register":"spoken","definition_en":"used to tell someone you agree with what they suggest","translation":"به کسی می گفت که با پیشنهاد او موافقید","example":"Yes, of course, anything you say.","example_translation":"بله، البته، هر چیزی که شما بگویید.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000983029.mp3"}]'::jsonb),
('d6e0b980-96ca-5480-9a61-35d50be89f35','ffba4e44-7cfe-5db9-b60b-3351855fb6fb',1,'adverb','A2','S1','W3',null,'[{"phrase":"not anywhere near","register":null,"definition_en":"not at all near","translation":"اصلا نزدیک نیست","example":"I wasn’t anywhere near him when he fell.","example_translation":"وقتی افتاد من نزدیکش نبودم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000942803.mp3"},{"phrase":"not get anywhere","register":"informal","definition_en":"to not be successful at all","translation":"تا اصلا موفق نباشیم","example":"You won’t get anywhere without qualifications.","example_translation":"بدون صلاحیت به جایی نخواهید رسید.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647170.mp3"},{"phrase":"not get somebody anywhere","register":"informal","definition_en":"if something does not get you anywhere, it does not change a situation or help you to achieve something","translation":"اگر چیزی شما را به جایی نرساند، موقعیتی را تغییر نمی‌دهد یا به شما در رسیدن به چیزی کمک نمی‌کند","example":"You can try writing to complain, but I don’t think it will get you anywhere.","example_translation":"می‌توانید برای شکایت بنویسید، اما فکر نمی‌کنم شما را به جایی برساند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000942817.mp3"},{"phrase":"not be going anywhere","register":"informal","definition_en":"to not be achieving success in your life","translation":"تا در زندگی خود به موفقیت نرسید","example":"He’s a nice enough lad, but he’s not going anywhere.","example_translation":"او به اندازه کافی پسر خوب است، اما جایی نمی رود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647177.mp3"}]'::jsonb),
