('ccf53c76-5466-5d3e-bb68-9b2368a84252','4f562ea2-49b5-5ea4-88f8-d4730d809327',1,'noun','A1','S1','W1',null,'[{"phrase":"be in business","register":"spoken","definition_en":"to be involved in business activities","translation":"در فعالیت های تجاری شرکت کنند","example":"The company has been in business for over 30 years.","example_translation":"این شرکت بیش از 30 سال است که در تجارت است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa020027.mp3"},{"phrase":"be back in business","register":null,"definition_en":"to be working or operating in a normal way again","translation":"دوباره به صورت عادی کار یا کار کند","example":"The band are back in business after a long break.","example_translation":"گروه پس از یک وقفه طولانی دوباره به کار خود بازگشته است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816878.mp3"},{"phrase":"go about your business","register":null,"definition_en":"to do the things that you normally do","translation":"برای انجام کارهایی که معمولا انجام می دهید","example":"The street was full of ordinary people going about their business.","example_translation":"خیابان مملو از مردم عادی بود که مشغول کار خود بودند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816882.mp3"},{"phrase":"make it your business to do something","register":null,"definition_en":"to make a special effort to do something","translation":"تلاش ویژه برای انجام کاری","example":"Ruth made it her business to get to know the customers.","example_translation":"روث کار خود را برای شناخت مشتریان آغاز کرد.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001047058.mp3"},{"phrase":"mean business","register":"informal","definition_en":"to be serious about doing something even if it involves harming someone","translation":"جدی بودن در انجام کاری حتی اگر شامل صدمه زدن به کسی باشد","example":"The border is guarded by troops who mean business.","example_translation":"مرز توسط نیروهایی که به معنای تجارت هستند محافظت می شود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001047093.mp3"},{"phrase":"unfinished business","register":null,"definition_en":"something you need to discuss further with someone or a situation that has not yet reached a satisfactory solution","translation":"چیزی که باید بیشتر با کسی بحث کنید یا موقعیتی که هنوز به راه حل رضایت بخشی نرسیده است","example":"The sudden death of a loved one can often leave the bereaved with an agonising sense of unfinished business.","example_translation":"مرگ ناگهانی یکی از عزیزان اغلب می‌تواند حس دردناکی از کار ناتمام را در فرد داغدار ایجاد کند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001786423.mp3"},{"phrase":"business is business","register":"spoken","definition_en":"used to say that profit is the most important thing to consider","translation":"قبلاً می گفت که سود مهمترین چیزی است که باید در نظر گرفت","example":"We can’t afford to employ someone who isn’t good at the job – business is business.","example_translation":"ما نمی توانیم فردی را استخدام کنیم که در این کار خوب نیست - تجارت یک تجارت است.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001046997.mp3"},{"phrase":"business as usual","register":null,"definition_en":"when someone or something is still working or operating normally when you think they might not be","translation":"وقتی کسی یا چیزی هنوز کار می کند یا به طور عادی کار می کند، در حالی که فکر می کنید ممکن است اینطور نباشد","example":"Despite last night’s scare, it was business as usual in the White House today.","example_translation":"علیرغم ترس دیشب، امروز در کاخ سفید طبق معمول بود.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001786425.mp3"},{"phrase":"not be in the business of doing something","register":null,"definition_en":"to not be intending to do something because you think it is a bad idea","translation":"قصد انجام کاری را نداشته باشید زیرا فکر می کنید ایده بدی است","example":"I’m not in the business of selling my best players.","example_translation":"من در کار فروش بهترین بازیکنانم نیستم.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001047115.mp3"},{"phrase":"and all that business","register":"spoken informal","definition_en":"and other things of the same general kind","translation":"و چیزهای دیگر از همین نوع عمومی","example":"She handles the publicity and all that business.","example_translation":"او تبلیغات و تمام آن تجارت را اداره می کند.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816885.mp3"},{"phrase":"do the business","register":"informal","definition_en":"to do what you are expected to do or what people want you to do","translation":"برای انجام کاری که از شما انتظار می رود یا آنچه مردم از شما می خواهند انجام دهید","example":"Come on, then, and do the business.","example_translation":"پس بیا و کار را انجام بده.","example_audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001816892.mp3"}]'::jsonb),
