('9f69a0ff-4f32-5285-a6cd-051eaf4359e0','9328cf30-0446-5a86-a83e-667b6fc1f25b',1,null,null,'spoken & written','complete or total',null,null,'مطلق، کامل، بی‌قیدوشرط','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I have absolute confidence in her.","translation":"من به او اطمینان کامل دارم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000964610.mp3"},{"sentence":"We don’t know with absolute certainty that the project will succeed.","translation":"ما با اطمینان کامل نمی دانیم که پروژه موفق خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619177.mp3"}]'::jsonb,2),
('85be8a13-f19f-584d-81f4-a45eda1d3b17','9328cf30-0446-5a86-a83e-667b6fc1f25b',2,null,null,'informal','used to emphasize your opinion about something or someone','[ only before noun ]',null,'برای تأکید بر نظر شما در مورد چیزی یا کسی استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Some of the stuff on TV is absolute rubbish.","translation":"برخی از چیزهای تلویزیون کاملاً آشغال است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619179.mp3"},{"sentence":"How did you do that? You’re an absolute genius.","translation":"چطور این کار را کردی؟ شما یک نابغه مطلق هستید","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000964603.mp3"},{"sentence":"That meal last night cost an absolute fortune.","translation":"آن وعده غذایی دیشب یک ثروت مطلق هزینه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619180.mp3"}]'::jsonb,3),
('0ad840cf-7edb-5b69-992f-3f273b5a1363','9328cf30-0446-5a86-a83e-667b6fc1f25b',3,null,null,'spoken & written','definite and not likely to change',null,null,'قطعی است و احتمال تغییر آن وجود ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We need absolute proof that he took the money.","translation":"ما به مدرک مطلق نیاز داریم که او پول را گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000964620.mp3"}]'::jsonb,1),
('652d5309-afb2-564f-968f-14513aaad066','9328cf30-0446-5a86-a83e-667b6fc1f25b',4,null,null,'spoken & written','not restricted or limited',null,null,'محدود یا محدود نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an absolute monarch","translation":"یک پادشاه مطلق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619181.mp3"},{"sentence":"Parents used to have absolute power over their children.","translation":"قبلاً والدین بر فرزندان خود قدرت مطلق داشتند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619182.mp3"}]'::jsonb,2),
('22d269dc-3ac4-5672-8743-630ce5362931','9328cf30-0446-5a86-a83e-667b6fc1f25b',5,null,null,'spoken & written','true, correct , and not changing in any situation',null,null,'درست، صحیح و در هیچ شرایطی تغییر نمی کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You have an absolute right to refuse medical treatment.","translation":"شما حق مطلق دارید که از درمان پزشکی امتناع کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619186.mp3"}]'::jsonb,1),
('0f18c03e-b55a-5e7c-9b8f-bbcef4a79201','9328cf30-0446-5a86-a83e-667b6fc1f25b',6,null,null,'spoken & written',null,null,'in absolute terms','مطلق، کامل، بی‌قیدوشرط','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('fab025ea-3ea6-5ead-908e-a35dc9cefe10','42449d21-5869-522b-966a-b6788251c075',1,null,null,'spoken & written','something that is considered to be true or right in all situations',null,null,'چیزی که در همه شرایط درست یا درست تلقی می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She believed in the importance of moral absolutes.","translation":"او به اهمیت مطلقات اخلاقی اعتقاد داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913539.mp3"}]'::jsonb,1),
('9d7c61c8-554a-5d89-a364-84dac9b64486','d756b74d-3dcf-59c1-8d07-16dca5d0a367',1,null,null,'spoken & written','relating to education , especially at college or university level','[ usually before noun ]',null,'دانشگاهی، آکادمیک؛ نظری','{}'::text[],'{}'::text[],array['academic qualifications He had the right experience and academic qualifications for the job.','academic performance Personal problems may affect a student’s academic performance.','academic achievements Girls’ academic achievements are at least as good as boys’.','academic standards (= levels that are considered to be acceptable ) The school has high academic standards.','academic research (= study of a subject, in order to discover new facts or test new ideas ) Many academic research projects take years to complete.','academic study After academic study, you have to gain practical experience.','an academic subject Children who are not good at academic subjects may excel in music or sport.','an academic discipline (= a subject that is studied at university ) the academic disciplines of linguistics, psychology and sociology','an academic career She wanted to pursue an academic career.','the academic year (= the time within a period of 12 months when students are studying at a school or university ) Language students spend the third academic year abroad.','the academic world (= the institutions, people etc involved in education ) In the academic world, the theory was received less approvingly.','academic freedom (= the freedom to study what you want ) There is concern for the academic freedom of both staff and students.']::text[],'[{"sentence":"He possessed no academic qualifications.","translation":"او هیچ مدرک تحصیلی نداشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000787871.mp3"},{"sentence":"a program to raise academic standards","translation":"برنامه ای برای ارتقای استانداردهای دانشگاهی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000787872.mp3"}]'::jsonb,2),
('f4f14d9c-fa37-5102-8ddd-f153ec7f586a','d756b74d-3dcf-59c1-8d07-16dca5d0a367',2,null,null,'spoken & written','concerned with studying from books, as opposed to practical work','[ usually before noun ]',null,'به مطالعه از روی کتاب، در مقابل کار عملی','{}'::text[],'{}'::text[],array['academic qualifications He had the right experience and academic qualifications for the job.','academic performance Personal problems may affect a student’s academic performance.','academic achievements Girls’ academic achievements are at least as good as boys’.','academic standards (= levels that are considered to be acceptable ) The school has high academic standards.','academic research (= study of a subject, in order to discover new facts or test new ideas ) Many academic research projects take years to complete.','academic study After academic study, you have to gain practical experience.','an academic subject Children who are not good at academic subjects may excel in music or sport.','an academic discipline (= a subject that is studied at university ) the academic disciplines of linguistics, psychology and sociology','an academic career She wanted to pursue an academic career.','the academic year (= the time within a period of 12 months when students are studying at a school or university ) Language students spend the third academic year abroad.','the academic world (= the institutions, people etc involved in education ) In the academic world, the theory was received less approvingly.','academic freedom (= the freedom to study what you want ) There is concern for the academic freedom of both staff and students.']::text[],'[{"sentence":"the study of art as an academic discipline","translation":"مطالعه هنر به عنوان یک رشته دانشگاهی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001619355.mp3"}]'::jsonb,1),
('152c4afe-c76d-5363-88e0-d1b8daee5388','d756b74d-3dcf-59c1-8d07-16dca5d0a367',3,null,null,'spoken & written','good at studying',null,null,'خوب در درس خواندن','{}'::text[],'{}'::text[],array['academic qualifications He had the right experience and academic qualifications for the job.','academic performance Personal problems may affect a student’s academic performance.','academic achievements Girls’ academic achievements are at least as good as boys’.','academic standards (= levels that are considered to be acceptable ) The school has high academic standards.','academic research (= study of a subject, in order to discover new facts or test new ideas ) Many academic research projects take years to complete.','academic study After academic study, you have to gain practical experience.','an academic subject Children who are not good at academic subjects may excel in music or sport.','an academic discipline (= a subject that is studied at university ) the academic disciplines of linguistics, psychology and sociology','an academic career She wanted to pursue an academic career.','the academic year (= the time within a period of 12 months when students are studying at a school or university ) Language students spend the third academic year abroad.','the academic world (= the institutions, people etc involved in education ) In the academic world, the theory was received less approvingly.','academic freedom (= the freedom to study what you want ) There is concern for the academic freedom of both staff and students.']::text[],'[{"sentence":"He’s not very academic.","translation":"او خیلی آکادمیک نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000787887.mp3"}]'::jsonb,1),
('3fd76491-6843-5e99-8090-bd17a040ea29','d756b74d-3dcf-59c1-8d07-16dca5d0a367',4,null,null,'spoken & written','if a discussion about something is academic, it is a waste of time because the speakers cannot change the existing situation',null,null,'اگر بحث در مورد چیزی آکادمیک باشد، اتلاف وقت است زیرا سخنرانان نمی توانند وضعیت موجود را تغییر دهند','{}'::text[],'{}'::text[],array['academic qualifications He had the right experience and academic qualifications for the job.','academic performance Personal problems may affect a student’s academic performance.','academic achievements Girls’ academic achievements are at least as good as boys’.','academic standards (= levels that are considered to be acceptable ) The school has high academic standards.','academic research (= study of a subject, in order to discover new facts or test new ideas ) Many academic research projects take years to complete.','academic study After academic study, you have to gain practical experience.','an academic subject Children who are not good at academic subjects may excel in music or sport.','an academic discipline (= a subject that is studied at university ) the academic disciplines of linguistics, psychology and sociology','an academic career She wanted to pursue an academic career.','the academic year (= the time within a period of 12 months when students are studying at a school or university ) Language students spend the third academic year abroad.','the academic world (= the institutions, people etc involved in education ) In the academic world, the theory was received less approvingly.','academic freedom (= the freedom to study what you want ) There is concern for the academic freedom of both staff and students.']::text[],'[{"sentence":"The question of where we go on holiday is purely academic since we don’t have any money.","translation":"این سوال که ما تعطیلات به کجا می رویم کاملاً آکادمیک است زیرا ما هیچ پولی نداریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000787883.mp3"}]'::jsonb,1),
('4e8ef7f2-a4f4-5602-8b59-b3e2ed0d2f1a','9a359b5f-0bd6-5641-ba4d-0ac43571b49f',1,null,null,'spoken & written','a teacher in a college or university',null,null,'یک معلم در کالج یا دانشگاه','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('539e0de0-e512-58bb-99ce-2e72a45b3646','82ce4104-7fbc-5ac4-b816-c25d87978de1',1,null,null,'spoken & written',null,null,'by accident','تصادف، حادثه','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('8ee41b86-ff0a-5e68-9c55-b3bbd2b7c03c','82ce4104-7fbc-5ac4-b816-c25d87978de1',2,null,null,'spoken & written','an event in which a car, train , plane etc is damaged and often someone is hurt','[ countable ]',null,'رویدادی که در آن ماشین، قطار، هواپیما و غیره آسیب می بیند و اغلب کسی صدمه می بیند','{}'::text[],'{}'::text[],array['a bad/serious accident There’s been a bad accident on the freeway. The road is closed following a serious accident.','a major accident News is coming in of a major rail accident.','a horrible/nasty/horrific accident We narrowly avoided a nasty accident. ‘This was an absolutely horrific accident, ’ said an ambulance spokesman.','a fatal accident (= in which someone is killed ) a fatal accident involving a bus and a cyclist','a minor accident (= one that is not serious ) The ice and poor visibility caused minor accidents all over the country.','a road/traffic accident The number of traffic accidents has gone down. Portugal has one of Western Europe’s worst road accident rates.','a car accident ( also an automobile accident American English formal ) He was badly injured in a car accident.','a plane accident/an airplane accident American English ( also a flying accident ) Holly died in a plane accident.','a rail accident/a train accident It was the country''s worst ever rail accident.','a hit-and-run accident (= when someone is hit by a driver who does not stop ) A woman is fighting for her life after a hit-and-run accident.','be involved in an accident formal: Your son has been involved in a car accident.','prevent an accident Steps have been taken to prevent a similar accident happening again.','an accident happens ( also an accident occurs formal ) No one saw the accident happen. Most road accidents occur in urban areas.','have an accident Young drivers are more likely to have accidents than older drivers.','an accident victim One of the accident victims is still trapped in his vehicle.','accident rates/statistics There is a relation between accident rates and the numbers of drivers on the road. a survey of the latest airline accident statistics','an accident investigation/inquiry The two deaths are the subject of an accident inquiry. Accident investigations often take months.','an accident investigator Accident investigators have been there all morning.','the scene of an accident (= the place where it happened ) Police were at the scene of the accident within minutes.']::text[],'[{"sentence":"Over 70,000 people are seriously injured every year in road accidents.","translation":"سالانه بیش از 70000 نفر در تصادفات جاده ای مجروح می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000010.mp3"},{"sentence":"The accident happened at the junction of Forest Road and Pine Walk.","translation":"این حادثه در تقاطع جاده جنگلی و پاین واک رخ داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654726.mp3"},{"sentence":"a train accident","translation":"یک تصادف قطار","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000011.mp3"}]'::jsonb,3),
('967b457c-6885-5781-b9f6-929f77673d4f','82ce4104-7fbc-5ac4-b816-c25d87978de1',3,null,null,'spoken & written','a situation in which someone is injured or something is damaged without anyone intending them to be','[ countable ]',null,'وضعیتی که در آن شخصی مجروح می شود یا چیزی آسیب می بیند بدون اینکه کسی قصد آن را داشته باشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Ken had an accident at work and had to go to hospital.","translation":"کن در محل کار تصادف کرد و مجبور شد به بیمارستان برود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654731.mp3"},{"sentence":"I’m sorry about breaking the vase – it was an accident (= I did not intend to do it ) .","translation":"از شکستن گلدان متاسفم - تصادفی بود (= من قصد انجام آن را نداشتم).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654735.mp3"},{"sentence":"He died in a climbing accident in the Himalayas.","translation":"او در یک حادثه کوهنوردی در هیمالیا جان باخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000012.mp3"},{"sentence":"She was injured in a freak accident (= an unusual accident ) when a wall suddenly collapsed.","translation":"او در یک تصادف عجیب مجروح شد (= یک تصادف غیر معمول) که ناگهان یک دیوار فرو ریخت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000013.mp3"},{"sentence":"I had a slight accident with your coffee.","translation":"من با قهوه شما تصادف مختصری داشتم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000014.mp3"},{"sentence":"They lost their lives in a tragic accident .","translation":"آنها در یک تصادف دلخراش جان خود را از دست دادند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000015.mp3"}]'::jsonb,6),
('666574fb-d8ee-5c5b-a437-26ab01d920fe','82ce4104-7fbc-5ac4-b816-c25d87978de1',4,null,null,'spoken & written','something that happens without anyone planning or intending it','[ countable, uncountable ]',null,'چیزی که بدون برنامه ریزی یا قصد کسی اتفاق می افتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"My third baby was an accident.","translation":"بچه سومم تصادف کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001833735.mp3"},{"sentence":"It is no accident that men fill most of the top jobs in nursing, while women remain on the lower grades.","translation":"تصادفی نیست که مردان اکثر مشاغل برتر را در پرستاری پر می کنند، در حالی که زنان در رده های پایین تر باقی می مانند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001654745.mp3"}]'::jsonb,2),
('ba96c1bd-90ca-541f-bfda-caec2ed6d016','82ce4104-7fbc-5ac4-b816-c25d87978de1',5,null,null,'spoken & written',null,null,'accidents (will) happen','تصادف، حادثه','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('c907d806-cfb7-5e45-875d-d1b399d6cfc1','82ce4104-7fbc-5ac4-b816-c25d87978de1',6,null,null,'spoken & written',null,null,'an accident waiting to happen','تصادف، حادثه','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('639dc93f-6bbb-5fc2-9aa9-5aa53a2a6b8c','37c32b8e-b462-517d-b1a1-13b5fcdc41fe',1,'information','اطلاعات','spoken & written','correct and true in every detail',null,null,'دقیق، صحیح، درست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The brochure tries to give a fair and accurate description of each hotel.","translation":"در این بروشور سعی شده است توضیحاتی منصفانه و دقیق از هر هتل ارائه شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000789144.mp3"},{"sentence":"Police believe Derek gave a reasonably accurate account of what happened.","translation":"پلیس بر این باور است که درک گزارش دقیقی از آنچه اتفاق افتاده ارائه کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645338.mp3"},{"sentence":"The evidence she gave to the court was not strictly accurate (= not exactly accurate ) .","translation":"شواهدی که او به دادگاه داد کاملاً دقیق نبود (= دقیق نبود).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645341.mp3"}]'::jsonb,3),
('eba2e6a9-fb55-5905-9966-619f61c2a823','37c32b8e-b462-517d-b1a1-13b5fcdc41fe',2,'measurement','اندازه گیری','spoken & written','measured or calculated correctly',null,null,'به درستی اندازه گیری یا محاسبه شده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It is difficult to get accurate figures on population numbers.","translation":"به دست آوردن ارقام دقیق در مورد تعداد جمعیت دشوار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645346.mp3"}]'::jsonb,1),
('231fb2ac-2f12-5d97-b73d-ca7f2d1708d8','37c32b8e-b462-517d-b1a1-13b5fcdc41fe',3,'machine','دستگاه','spoken & written','a machine that is accurate is able to do something in an exact way without making a mistake',null,null,'ماشینی که دقیق باشد قادر است کاری را به روشی دقیق و بدون اشتباه انجام دهد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The cutter is accurate to within ½ a millimetre.","translation":"دقت کاتر تا ½ میلی متر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000789152.mp3"}]'::jsonb,1),
('e0978d17-c6c4-5c24-9303-be489a034834','37c32b8e-b462-517d-b1a1-13b5fcdc41fe',4,'well-aimed','هدفمند','spoken & written','an accurate shot , throw etc succeeds in hitting or reaching the thing that it is intended to hit',null,null,'یک شوت دقیق، پرتاب و غیره موفق می شود به چیزی که در نظر گرفته شده است ضربه بزند یا به آن برسد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an accurate shot","translation":"یک ضربه دقیق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000789156.mp3"},{"sentence":"accurate bowling","translation":"بولینگ دقیق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645349.mp3"}]'::jsonb,2),
('342b21f5-8bb0-5700-bb9a-9f7e2b16f859','a3a9c7b7-1be9-552f-bed2-ccb82a6b1d94',1,null,null,'spoken & written','someone who works hard doing practical things to achieve social or political change',null,null,'کنشگر، فعال (سیاسی/اجتماعی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('e6b53038-edff-533a-ac22-c0fcfe2170fc','94a49650-d884-53f1-8eb3-1107b6ab5837',1,null,null,'spoken & written','things that people do, especially in order to achieve a particular aim','[ countable, uncountable ]',null,'فعالیت، کنش؛ برنامه','{}'::text[],'{}'::text[],array['take part in an activity ( also participate in an activity formal ) The children were encouraged to take part in several different activities.','engage in an activity formal (= take part ) Police suspect he may have engaged in criminal activities.','be involved in an activity The men were involved in terrorist activities.','do an activity He doesn’t do a lot of physical activity.','political activity Political activity is closely controlled by the government.','economic activity The current level of economic activity will influence business confidence.','business/commercial activity Internet shopping is a rapidly developing area of business activity.','human activity There was no sign of any human activity.','criminal/illegal activity The bar was being used for illegal activities.','terrorist activity The police took extra measures to protect the public against terrorist activity.','outdoor activities The college is well situated for students who are interested in outdoor activities.','physical activity It’s important to do some kind of regular physical activity.','mental activity Your mental activity starts to slow down as you grow old.','leisure activities I don’t have much time for leisure activities.','classroom activities He didn’t really take part in classroom activities.','cultural activities There is plenty of opportunity for children to express themselves in creative and cultural activities.','the level of activity The level of economic activity has increased.']::text[],'[{"sentence":"Everyone is free to engage in peaceful political activity.","translation":"همه آزادند که در فعالیت های سیاسی مسالمت آمیز شرکت کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776522.mp3"},{"sentence":"fund-raising activities","translation":"فعالیت های جمع آوری سرمایه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000021.mp3"},{"sentence":"Regular physical activity helps to control your weight.","translation":"فعالیت بدنی منظم به کنترل وزن کمک می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776526.mp3"}]'::jsonb,3),
('35200ed9-e3d5-5362-86eb-08b9edd837d6','94a49650-d884-53f1-8eb3-1107b6ab5837',2,null,null,'spoken & written','something that you do because you enjoy it','[ countable usually plural ]',null,'کاری که انجام می دهید چون از آن لذت می برید','{}'::text[],'{}'::text[],array['take part in an activity ( also participate in an activity formal ) The children were encouraged to take part in several different activities.','engage in an activity formal (= take part ) Police suspect he may have engaged in criminal activities.','be involved in an activity The men were involved in terrorist activities.','do an activity He doesn’t do a lot of physical activity.','political activity Political activity is closely controlled by the government.','economic activity The current level of economic activity will influence business confidence.','business/commercial activity Internet shopping is a rapidly developing area of business activity.','human activity There was no sign of any human activity.','criminal/illegal activity The bar was being used for illegal activities.','terrorist activity The police took extra measures to protect the public against terrorist activity.','outdoor activities The college is well situated for students who are interested in outdoor activities.','physical activity It’s important to do some kind of regular physical activity.','mental activity Your mental activity starts to slow down as you grow old.','leisure activities I don’t have much time for leisure activities.','classroom activities He didn’t really take part in classroom activities.','cultural activities There is plenty of opportunity for children to express themselves in creative and cultural activities.','the level of activity The level of economic activity has increased.']::text[],'[{"sentence":"leisure activities","translation":"فعالیت های اوقات فراغت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000022.mp3"},{"sentence":"outdoor activities such as hiking or climbing","translation":"فعالیت در فضای باز مانند پیاده روی یا کوهنوردی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609414.mp3"}]'::jsonb,2),
('7d6c9a8e-937e-5d8f-a8c6-1d924812575f','94a49650-d884-53f1-8eb3-1107b6ab5837',3,null,null,'spoken & written','a situation in which a lot of things are happening or a lot of things are being done','[ uncountable ]',null,'موقعیتی که در آن اتفاقات زیادی در حال وقوع است یا کارهای زیادی در حال انجام است','{}'::text[],'{}'::text[],array['take part in an activity ( also participate in an activity formal ) The children were encouraged to take part in several different activities.','engage in an activity formal (= take part ) Police suspect he may have engaged in criminal activities.','be involved in an activity The men were involved in terrorist activities.','do an activity He doesn’t do a lot of physical activity.','political activity Political activity is closely controlled by the government.','economic activity The current level of economic activity will influence business confidence.','business/commercial activity Internet shopping is a rapidly developing area of business activity.','human activity There was no sign of any human activity.','criminal/illegal activity The bar was being used for illegal activities.','terrorist activity The police took extra measures to protect the public against terrorist activity.','outdoor activities The college is well situated for students who are interested in outdoor activities.','physical activity It’s important to do some kind of regular physical activity.','mental activity Your mental activity starts to slow down as you grow old.','leisure activities I don’t have much time for leisure activities.','classroom activities He didn’t really take part in classroom activities.','cultural activities There is plenty of opportunity for children to express themselves in creative and cultural activities.','the level of activity The level of economic activity has increased.']::text[],'[{"sentence":"The office was suddenly full of frantic activity .","translation":"دفتر ناگهان پر از فعالیت دیوانه وار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000023.mp3"},{"sentence":"The farm was always a hive of activity at this time of year.","translation":"مزرعه در این زمان از سال همیشه محل فعالیت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000024.mp3"}]'::jsonb,2),
('9255cc58-f9a5-590b-8967-ca1d28ece032','e0a3bdca-03b5-5ab3-944b-a8199006b7d4',1,null,null,'spoken','used to add new information to what you have just said, to give your opinion , or to start a new conversation','[ sentence adverb ]',null,'در واقع، راستش؛ واقعاً','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’ve known Barbara for years. Since we were babies, actually.","translation":"باربارا را سال هاست می شناسم. از زمانی که ما بچه بودیم، در واقع.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000968688.mp3"},{"sentence":"Actually, on second thoughts, I don’t think I want to go out tonight.","translation":"در واقع، در مورد فکر دوم، فکر نمی‌کنم امشب بخواهم بیرون بروم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609448.mp3"}]'::jsonb,2),
('ff72ed7a-9bf2-53f3-8868-1012fb3efc67','e0a3bdca-03b5-5ab3-944b-a8199006b7d4',2,null,null,'spoken & written','used to emphasize the real or exact truth of a situation, rather than what people may think',null,null,'برای تأکید بر حقیقت واقعی یا دقیق یک موقعیت، به جای آنچه مردم ممکن است فکر کنند، استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"What time are you actually leaving?","translation":"راستی ساعت چند میری؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609449.mp3"},{"sentence":"Labor costs have actually fallen.","translation":"هزینه های نیروی کار در واقع کاهش یافته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609450.mp3"},{"sentence":"‘Disappointed?’ ‘No, actually I’m rather glad.’","translation":"«ناامید؟» «نه، در واقع من خیلی خوشحالم».","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000968696.mp3"}]'::jsonb,3),
('dc697f18-68d6-5b6f-b7d7-0ad7592b64f4','9197683a-0f76-5847-88f9-132878f83afb',1,null,null,'spoken & written',null,null,'in addition','افزودن، اضافه‌شدن؛ اضافه (در ریاضی)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('db37c4d5-871f-5b36-a464-fd1cac7ab28b','9197683a-0f76-5847-88f9-132878f83afb',2,null,null,'spoken & written','the act of adding something to something else','[ uncountable ]',null,'عمل افزودن چیزی به چیز دیگری','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The addition of networking facilities will greatly enhance the system.","translation":"افزودن امکانات شبکه به شدت سیستم را ارتقا می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000970274.mp3"},{"sentence":"Turn sparkling wine into Buck’s Fizz with the addition of chilled orange juice.","translation":"شراب گازدار را با اضافه کردن آب پرتقال خنک به Buck’s Fizz تبدیل کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001609959.mp3"}]'::jsonb,2),
('b520d293-7ab8-5ba2-90e2-2f03ecdfbfeb','9197683a-0f76-5847-88f9-132878f83afb',3,null,null,'spoken & written','something that is added to something else, often in order to improve it','[ countable ]',null,'چیزی که اغلب به منظور بهبود آن به چیز دیگری اضافه می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This excellent book will be a welcome addition to the library of any student.","translation":"این کتاب عالی برای کتابخانه هر دانش آموزی مورد استقبال قرار خواهد گرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000970281.mp3"},{"sentence":"the latest addition to our designer range","translation":"جدیدترین محصول اضافه شده به مجموعه طراحان ما","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776805.mp3"}]'::jsonb,2),
('b6324b89-d40f-59a9-8279-134bbdb6b650','9197683a-0f76-5847-88f9-132878f83afb',4,null,null,'spoken & written','the process of adding numbers or amounts to make a total','[ uncountable ]',null,'فرآیند جمع کردن اعداد یا مقادیر برای ایجاد یک کل','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('ad7b4ba0-de36-5401-91cd-689f2fa65e14','9197683a-0f76-5847-88f9-132878f83afb',5,null,null,'spoken & written','an extra room that is added to a building','[ countable ]',null,'یک اتاق اضافی که به یک ساختمان اضافه شده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"They built a big addition onto the back of the house.","translation":"آنها یک اضافی بزرگ در پشت خانه ساخته اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000970297.mp3"}]'::jsonb,1),
('74f659a7-c0df-5273-b5ff-95443c46495d','c0820d29-dc13-5994-b10d-52346750f52d',1,null,null,'spoken & written','enough in quantity or of a good enough quality for a particular purpose',null,null,'کافی، بسنده',array['sufficient']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Farmers have been slow to make adequate provision for their retirement.","translation":"کشاورزان در تهیه تدارکات کافی برای بازنشستگی خود کند بوده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776540.mp3"},{"sentence":"Some creams we tested failed to give adequate protection against UV light.","translation":"برخی از کرم‌هایی که آزمایش کردیم نتوانستند محافظت کافی در برابر اشعه ماوراء بنفش داشته باشند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610066.mp3"},{"sentence":"The standard of his work is barely adequate .","translation":"استاندارد کار او به سختی کافی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610074.mp3"},{"sentence":"The company has yet to provide an adequate explanation for its actions.","translation":"این شرکت هنوز توضیح کافی برای اقدامات خود ارائه نکرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610078.mp3"},{"sentence":"Are the parking facilities adequate for 50 cars?","translation":"آیا امکانات پارکینگ برای 50 خودرو مناسب است؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000791885.mp3"},{"sentence":"The lunchtime menu is more than adequate to satisfy the biggest appetite.","translation":"منوی زمان ناهار برای ارضای بزرگترین اشتها کافی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001610084.mp3"}]'::jsonb,6),
('cfe62f84-6d4a-52f3-b28d-32d9de19c250','c0820d29-dc13-5994-b10d-52346750f52d',2,null,null,'spoken & written','fairly good but not excellent',null,null,'نسبتا خوب است اما عالی نیست','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Her performance was adequate but lacked originality.","translation":"اجرای او کافی بود اما فاقد اصالت بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000791896.mp3"}]'::jsonb,1),
