('0e3d78e4-abaf-5569-ad6e-25c233f0cfa5','99847cbb-2020-52c3-8c0e-5425dff7e806',2,null,null,'spoken & written','studying or dealing with a school subject at a difficult level',null,null,'مطالعه یا پرداختن به یک موضوع مدرسه در سطح دشوار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"advanced learners of English","translation":"زبان آموزان پیشرفته انگلیسی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793398.mp3"},{"sentence":"advanced physics","translation":"فیزیک پیشرفته","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793399.mp3"}]'::jsonb,2),
('751fca2e-3ded-536d-a3ad-d82bcfeae498','99847cbb-2020-52c3-8c0e-5425dff7e806',3,null,null,'spoken & written','having reached a late point in time or development',null,null,'رسیدن به یک نقطه دیر هنگام در زمان یا توسعه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The disease was too far advanced to be treated.","translation":"این بیماری خیلی پیشرفت کرده بود که قابل درمان نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000793403.mp3"}]'::jsonb,1),
