('3e13583c-ab56-5976-94f5-1a4fc099a9f5','5cfc86f9-c52d-5bf2-8460-a8b6695451c4',1,null,null,'spoken & written','easy to notice',null,null,'آشکار، بدیهی؛ ظاهراً درست',array['obvious']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It soon became apparent that we had a major problem.","translation":"خیلی زود مشخص شد که ما یک مشکل اساسی داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001783366.mp3"},{"sentence":"It is apparent from scientific studies that the drug has some fairly nasty side effects.","translation":"از مطالعات علمی مشخص است که این دارو عوارض جانبی نسبتاً بدی دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647390.mp3"},{"sentence":"It was apparent to everyone that he was seriously ill.","translation":"برای همه مشخص بود که او به شدت بیمار است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001783367.mp3"},{"sentence":"The difference in quality was immediately apparent .","translation":"تفاوت در کیفیت بلافاصله آشکار شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647394.mp3"},{"sentence":"He left suddenly, for no apparent reason .","translation":"او بدون هیچ دلیلی ناگهانی رفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647398.mp3"}]'::jsonb,5),
('3b4373c9-6b0f-5da7-958a-1f5010f33c7c','5cfc86f9-c52d-5bf2-8460-a8b6695451c4',2,null,null,'spoken & written','seeming to have a particular feeling or attitude , although this may not be true',null,null,'به نظر می رسد که احساس یا نگرش خاصی دارد، اگرچه ممکن است این درست نباشد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He did well in his exams, despite his apparent lack of interest in his work.","translation":"او علیرغم عدم علاقه ظاهری به کارش، در امتحاناتش خوب جواب داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001647402.mp3"}]'::jsonb,1),
('babc7149-e42b-5b51-b52b-324ffa45df33','c639bcf1-3711-5eed-831b-c426eb4bc901',1,'method','روش','spoken & written','a method of doing something or dealing with a problem','[ countable ]',null,'روش، رویکرد؛ نزدیک شدن','{}'::text[],'{}'::text[],array['a new/different/fresh/alternative approach a new approach to pollution control','a positive approach (= showing that you believe something can be done ) A positive approach is essential in beating pain.','a creative approach (= thinking of new ideas and methods ) International business requires a more creative approach.','a general/broad approach Many governments have pursued this general approach to economic policy.','a direct approach We would do better to adopt a direct approach and tackle the problem at its source.','a practical approach Women often take a more practical approach.','a pragmatic approach (= dealing with problems in a way that is not limited by a strict set of principles ) a pragmatic approach to management problems','a balanced approach (= considering everything in a sensible way ) The president spoke in favour of a calm and balanced approach.','a tough approach (= dealing with something in a severe way ) The council adopted a tough approach to fighting crime.','a cautious approach China has followed a more cautious approach.','a flexible approach (= using different methods if necessary ) We have a flexible approach to our clients’ requirements.','a traditional/conservative approach This is different from the traditional approach to high school teaching.','an unorthodox approach (= not the same as people usually use ) It’s an unorthodox approach that her doctor doesn’t recommend for everyone.','a scientific/systematic approach a scientific approach to the study of language','have an approach In the US they have a somewhat different approach.','take/adopt an approach (= use an approach ) There were concerns that Beijing would take a tougher approach.','use an approach This approach has been used for a number of major investigations.','try an approach Some scientists have been trying an alternative approach.','prefer/favour an approach I prefer a traditional approach.']::text[],'[{"sentence":"a new approach to teaching languages","translation":"رویکردی جدید برای آموزش زبان","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945643.mp3"},{"sentence":"He decided to adopt a different approach and teach the Bible through story-telling.","translation":"او تصمیم گرفت رویکرد متفاوتی اتخاذ کند و کتاب مقدس را از طریق داستان گویی آموزش دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913380.mp3"},{"sentence":"This book takes an unorthodox approach to art criticism.","translation":"این کتاب رویکردی نامتعارف به نقد هنری دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913386.mp3"},{"sentence":"organizations which take a positive approach to creative thinking","translation":"سازمان هایی که رویکرد مثبتی به تفکر خلاق دارند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913392.mp3"}]'::jsonb,4),
