('c2c6e044-3332-5a94-84ce-29fb3a749a8a','c639bcf1-3711-5eed-831b-c426eb4bc901',6,'aircraft','هواپیما','spoken & written','the final part of a plane ’s flight , before it lands at an airport','[ countable ]',null,'قسمت پایانی پرواز هواپیما، قبل از فرود در فرودگاه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was clear to land so we made our approach .","translation":"فرود آمدن واضح بود بنابراین ما نزدیک شدیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672146.mp3"}]'::jsonb,1),
('0b920a2e-a229-57a9-95bf-8cabe45a0885','41aeaeb7-cd0e-53cb-b730-bea5526f9ca5',1,'move towards','حرکت به سمت','spoken & written','to move towards or nearer to someone or something','[ intransitive, transitive ]',null,'نزدیک شدن، حرکت به سمت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"As I approached the house, I noticed a light on upstairs.","translation":"وقتی به خانه نزدیک شدم، متوجه نوری در طبقه بالا شدم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986669.mp3"},{"sentence":"She heard footsteps approaching.","translation":"صدای قدم هایی را شنید که نزدیک می شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986670.mp3"}]'::jsonb,2),
('628e62ee-a693-59cd-8145-88a2c3ed468a','41aeaeb7-cd0e-53cb-b730-bea5526f9ca5',2,'ask','بپرسید','spoken & written','to ask someone for something, or ask them to do something, especially when you are asking them for the first time or when you are not sure if they will do it','[ transitive ]','approachable','از کسی چیزی بخواهید، یا از او بخواهید کاری انجام دهد، به خصوص زمانی که برای اولین بار از او می خواهید یا مطمئن نیستید که آیا آن کار را انجام خواهد داد یا خیر.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Students should be able to approach teachers for advice.","translation":"دانش آموزان باید بتوانند برای مشاوره به معلمان مراجعه کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986680.mp3"},{"sentence":"The charity approached several stores about giving food aid.","translation":"این موسسه خیریه در مورد کمک غذایی به چندین فروشگاه مراجعه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986683.mp3"},{"sentence":"I have already been approached by several other companies (= offered a job, work etc ) .","translation":"قبلاً چندین شرکت دیگر با من تماس گرفته اند (= پیشنهاد کار، کار و غیره).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672427.mp3"}]'::jsonb,3),
('3f81d6e8-4868-5c5c-9361-9bba04fcf0f4','41aeaeb7-cd0e-53cb-b730-bea5526f9ca5',3,'future event','رویداد آینده','spoken & written','if an event or a particular time approaches, or you approach it, it is coming nearer and will happen soon','[ intransitive, transitive ]',null,'اگر یک رویداد یا زمان خاصی نزدیک شود، یا به آن نزدیک شوید، نزدیکتر می شود و به زودی اتفاق می افتد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She was then approaching the end of her career.","translation":"او سپس به پایان کار خود نزدیک می شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986694.mp3"},{"sentence":"The time is fast approaching when we will have to make a decision.","translation":"زمان آن نزدیک است که باید تصمیم بگیریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672432.mp3"},{"sentence":"With winter approaching, many animals are storing food.","translation":"با نزدیک شدن به زمستان، بسیاری از حیوانات در حال ذخیره غذا هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672436.mp3"}]'::jsonb,3),
('891446dc-f051-54b2-9a5c-ad47153740c8','41aeaeb7-cd0e-53cb-b730-bea5526f9ca5',4,'deal with','با','spoken & written','to begin to deal with a situation or problem in a particular way or with a particular attitude','[ transitive ]',null,'شروع به برخورد با یک موقعیت یا مشکل به روشی خاص یا با نگرش خاصی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It might be possible to approach the problem in a different way.","translation":"شاید بتوان به روش دیگری به مشکل برخورد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986713.mp3"}]'::jsonb,1),
('7ad4acba-04f4-56e1-8c82-a0b351dcfe61','41aeaeb7-cd0e-53cb-b730-bea5526f9ca5',5,'almost','تقریبا','spoken & written','to be almost equal to something','[ intransitive, transitive ]',null,'تقریبا برابر با چیزی بودن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"temperatures approaching 35° C","translation":"دمای نزدیک به 35 درجه سانتیگراد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000986702.mp3"},{"sentence":"He’s never had anything approaching a normal life.","translation":"او هرگز چیزی نزدیک به یک زندگی عادی نداشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672441.mp3"}]'::jsonb,2),
('eae29b32-592b-5c27-9e10-312fe4f7cea7','779f27fd-00c9-54ad-9c97-10f798f056d9',1,null,null,'spoken & written','when a plan, decision , or person is officially accepted','[ countable, uncountable ]',null,'تأیید، پذیرش رسمی؛ رضایت','{}'::text[],'{}'::text[],array['give/grant approval Congress gave final approval on October 8.','get/receive/obtain/win approval For over twenty years it was impossible for NASA to get approval for this mission.','require/need approval A multimillion pound project will require approval by the full board of directors.','seek approval You will need to make an appointment with the bank to seek approval for the loan.','submit something for approval (= give a plan, piece of writing etc to someone in authority for them to consider or approve ) The final design will be submitted for approval next month.','formal/official approval Finance ministers gave their formal approval in July.','parliamentary approval The law is still awaiting parliamentary approval.','Congressional approval His appointment was subject to Congressional approval.','government/Senate approval It takes an average of twelve years for a successful drug to go from initial research to final government approval.','planning approval (= official approval needed before building something ) The construction work will be subject to planning approval.','final approval The document’s final approval had to come from the pope.','parental approval Students must first obtain parental approval.','be subject to approval (= be dependent upon someone’s approval before happening ) The merger is subject to approval by shareholders.','a seal/stamp of approval (= official approval ) You must not make decisions without your manager’s seal of approval.']::text[],'[{"sentence":"The president has already given his approval to the plan.","translation":"رئیس جمهور قبلاً با این طرح موافقت کرده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941294.mp3"},{"sentence":"It is just three months since we received official approval to go ahead with the project.","translation":"تنها سه ماه از دریافت مجوز رسمی برای ادامه پروژه می گذرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941298.mp3"},{"sentence":"A company cannot be sold without the approval of the shareholders.","translation":"یک شرکت بدون تایید سهامداران قابل فروش نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672189.mp3"},{"sentence":"The bill will be submitted for approval by Congress.","translation":"این لایحه برای تصویب در کنگره ارائه خواهد شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945782.mp3"},{"sentence":"The president would appoint the Council of Ministers, subject to the approval of the National Assembly.","translation":"رئیس جمهور شورای وزیران را با تصویب مجلس شورای ملی منصوب می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913464.mp3"},{"sentence":"The IMF has given its seal of approval to the government’s economic strategy.","translation":"صندوق بین المللی پول مهر تایید خود را بر استراتژی اقتصادی دولت داده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945790.mp3"},{"sentence":"appointments requiring parliamentary approval","translation":"انتصاباتی که نیاز به تصویب مجلس دارند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001913468.mp3"}]'::jsonb,7),
('d46d5087-2f32-55a8-99d6-0db34cd780d2','779f27fd-00c9-54ad-9c97-10f798f056d9',2,null,null,'formal','when someone likes something or someone and thinks that they are good','[ uncountable ]',null,'وقتی کسی چیزی یا کسی را دوست دارد و فکر می کند که خوب است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"A murmur of approval passed through the crowd.","translation":"زمزمه تایید از میان جمعیت گذشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941306.mp3"},{"sentence":"They clapped their hands in approval.","translation":"آنها به نشانه تایید دست زدند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000945771.mp3"},{"sentence":"His ideas have won widespread public approval (= many people agree with them and think they are good ) .","translation":"ایده های او مورد تایید عمومی گسترده قرار گرفته است (= بسیاری از مردم با آنها موافق هستند و فکر می کنند خوب هستند).","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941309.mp3"},{"sentence":"Does the design meet with your approval (= do you like it? ) ?","translation":"آیا طرح با تایید شما روبرو می شود (= آیا آن را دوست دارید؟ )؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941316.mp3"},{"sentence":"Children are always seeking approval from their parents.","translation":"کودکان همیشه به دنبال تایید والدین خود هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001941321.mp3"},{"sentence":"She looked to Greg for approval .","translation":"او برای تایید به گرگ نگاه کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001672204.mp3"}]'::jsonb,6),
('cebdb974-fefb-50be-b434-16ea4eea8ded','779f27fd-00c9-54ad-9c97-10f798f056d9',3,null,null,'spoken & written',null,null,'on approval','تأیید، پذیرش رسمی؛ رضایت','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('675b9d8c-a224-5243-851b-c45f3ed534ae','3a8fed21-1c18-53a2-abf4-41991c232f12',1,null,null,'spoken & written','a situation in which two or more people disagree , often angrily','[ countable ]',null,'جدل، بحث؛ استدلال، دلیل','{}'::text[],'{}'::text[],array['have an argument I could hear my parents having an argument downstairs.','get into an argument/become involved in an argument She didn’t want to get into another argument about money. I left to avoid becoming involved in an argument.','start/cause an argument He was deliberately trying to start an argument. Money often causes arguments.','avoid an argument I was anxious to avoid an argument.','win/lose an argument The party hopes to win the argument about how to reform the health system. The first one who resorts to violence is usually the one who’s lost the argument.','an argument breaks out (= it starts ) The men were drunk and an argument soon broke out.','an argument erupts (= a big argument suddenly starts ) A bitter argument erupted between the brothers over who should inherit the money.','a big/huge/massive argument There was a big argument about whether we should move to a new house.','a heated argument (= involving very strong feelings ) Someone was having a heated argument with a police officer.','a bitter argument There are bitter arguments about whether he was a hero or a war criminal.','a furious/fierce argument As soon as she had gone a furious argument broke out.','a violent argument The singer was hurt in a violent argument with her husband.']::text[],'[{"sentence":"She had a big argument with her husband.","translation":"دعوای شدیدی با شوهرش داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000094.mp3"},{"sentence":"There have been a lot of arguments about who was responsible for the accident.","translation":"بحث های زیادی در مورد اینکه چه کسی مسئول این حادثه بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000095.mp3"}]'::jsonb,2),
('b53ddcbd-4cfc-5eae-b068-59cd713bc619','3a8fed21-1c18-53a2-abf4-41991c232f12',2,null,null,'spoken & written','a set of reasons that show that something is true or untrue , right or wrong etc','[ countable ]',null,'مجموعه ای از دلایل که نشان می دهد چیزی درست یا نادرست، درست یا غلط است و غیره','{}'::text[],'{}'::text[],array['have an argument I could hear my parents having an argument downstairs.','get into an argument/become involved in an argument She didn’t want to get into another argument about money. I left to avoid becoming involved in an argument.','start/cause an argument He was deliberately trying to start an argument. Money often causes arguments.','avoid an argument I was anxious to avoid an argument.','win/lose an argument The party hopes to win the argument about how to reform the health system. The first one who resorts to violence is usually the one who’s lost the argument.','an argument breaks out (= it starts ) The men were drunk and an argument soon broke out.','an argument erupts (= a big argument suddenly starts ) A bitter argument erupted between the brothers over who should inherit the money.','a big/huge/massive argument There was a big argument about whether we should move to a new house.','a heated argument (= involving very strong feelings ) Someone was having a heated argument with a police officer.','a bitter argument There are bitter arguments about whether he was a hero or a war criminal.','a furious/fierce argument As soon as she had gone a furious argument broke out.','a violent argument The singer was hurt in a violent argument with her husband.']::text[],'[{"sentence":"We need to provide a convincing argument as to why the system should be changed.","translation":"ما باید استدلال قانع کننده ای ارائه کنیم که چرا سیستم باید تغییر کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001676477.mp3"},{"sentence":"a powerful argument against smoking","translation":"یک استدلال قوی علیه سیگار کشیدن","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000948692.mp3"},{"sentence":"A good argument can be made for comparing the IT revolution with the invention of writing itself.","translation":"می توان استدلال خوبی برای مقایسه انقلاب فناوری اطلاعات با اختراع خود نوشتن ارائه داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000948689.mp3"},{"sentence":"the arguments in favour of banning tobacco advertising","translation":"استدلال به نفع ممنوعیت تبلیغات دخانیات","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001676487.mp3"},{"sentence":"the familiar argument that the costs outweigh the benefits","translation":"استدلال آشنا مبنی بر اینکه هزینه ها بیشتر از منافع است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000948695.mp3"}]'::jsonb,5),
('304578cb-de81-5eec-8228-bbcc85f9abad','3a8fed21-1c18-53a2-abf4-41991c232f12',3,null,null,'spoken & written','when you disagree with something or question whether it is right','[ uncountable ]',null,'وقتی با چیزی مخالف هستید یا اینکه درست است یا خیر','{}'::text[],'{}'::text[],array['have an argument I could hear my parents having an argument downstairs.','get into an argument/become involved in an argument She didn’t want to get into another argument about money. I left to avoid becoming involved in an argument.','start/cause an argument He was deliberately trying to start an argument. Money often causes arguments.','avoid an argument I was anxious to avoid an argument.','win/lose an argument The party hopes to win the argument about how to reform the health system. The first one who resorts to violence is usually the one who’s lost the argument.','an argument breaks out (= it starts ) The men were drunk and an argument soon broke out.','an argument erupts (= a big argument suddenly starts ) A bitter argument erupted between the brothers over who should inherit the money.','a big/huge/massive argument There was a big argument about whether we should move to a new house.','a heated argument (= involving very strong feelings ) Someone was having a heated argument with a police officer.','a bitter argument There are bitter arguments about whether he was a hero or a war criminal.','a furious/fierce argument As soon as she had gone a furious argument broke out.','a violent argument The singer was hurt in a violent argument with her husband.']::text[],'[{"sentence":"Ian accepted the suggestion without argument.","translation":"ایان این پیشنهاد را بدون استدلال پذیرفت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000948702.mp3"},{"sentence":"If, for the sake of argument, you aren’t offered the job, what will you do?","translation":"اگر به خاطر استدلال، این کار به شما پیشنهاد نشود، چه خواهید کرد؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000948706.mp3"}]'::jsonb,2),
('4c1e3147-7ca4-521e-b704-d4c093a6e2a7','102d4206-8c83-5a1a-8852-fd630d42ad32',1,null,null,'spoken & written','the opinions and feelings that you usually have about something, especially when this is shown in your behaviour','[ countable, uncountable ]',null,'نگرش، نگره؛ رفتار و برخورد','{}'::text[],'{}'::text[],array['good/bad a lazy student with a bad attitude','positive/negative A positive attitude is essential if you want to be successful. Many teenagers have a very negative attitude towards cooking.','relaxed On Bali, there is a healthier, more relaxed attitude to life.','favourable (= having a good opinion of something or someone ) Older people tend to have a favourable attitude to the police.','critical (= showing you disagree with or disapprove of someone or something ) People’s attitude towards US foreign policy has become increasingly critical.','ambivalent (= not sure if you approve of something ) The public have a rather ambivalent attitude towards science.','cavalier (= very careless, especially about something serious or important ) his cavalier attitude to the truth','patronizing/condescending (= showing that you think you are more important or intelligent than someone ) complaints about patronising attitudes towards women','aggressive/hostile (= showing anger ) Their attitude suddenly became more aggressive.','public attitudes/people’s attitudes Public attitudes have changed.','political attitudes a survey of people’s political attitudes','mental attitude There is a strong connection between health and mental attitude.','somebody’s whole attitude His whole attitude seemed different.','the general attitude His general attitude to our situation was unsympathetic.','have/take/adopt an attitude Not everyone takes a positive attitude towards modern art.','somebody’s attitude changes As you get older, your attitude changes.','an attitude exists This attitude no longer exists in the church.','somebody’s attitude hardens (= they feel less sympathy and they want to be stricter or firmer ) People’s attitudes towards sex offenders have hardened.','an attitude of mind British English (= a way of thinking ) Being young is simply an attitude of mind.','somebody has an attitude problem (= someone is not helpful or pleasant to be with ) Some of the male students have a real attitude problem.']::text[],'[{"sentence":"As soon as they found out I was a doctor, their whole attitude changed.","translation":"به محض اینکه فهمیدند من دکتر هستم، کل نگرش آنها تغییر کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000997311.mp3"},{"sentence":"The people have a very positive attitude to life.","translation":"مردم نگرش بسیار مثبتی به زندگی دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000123.mp3"}]'::jsonb,2),
('2ab2d125-24cd-5b49-9b6d-113171b5fe4c','102d4206-8c83-5a1a-8852-fd630d42ad32',2,null,null,'informal','a style of dressing , behaving etc that shows you have the confidence to do unusual and exciting things without caring what other people think','[ uncountable ]',null,'یک سبک لباس پوشیدن، رفتار و غیره که نشان می دهد شما اعتماد به نفس دارید که کارهای غیرعادی و هیجان انگیز انجام دهید بدون اینکه اهمیتی به نظر دیگران بدهید.','{}'::text[],'{}'::text[],array['good/bad a lazy student with a bad attitude','positive/negative A positive attitude is essential if you want to be successful. Many teenagers have a very negative attitude towards cooking.','relaxed On Bali, there is a healthier, more relaxed attitude to life.','favourable (= having a good opinion of something or someone ) Older people tend to have a favourable attitude to the police.','critical (= showing you disagree with or disapprove of someone or something ) People’s attitude towards US foreign policy has become increasingly critical.','ambivalent (= not sure if you approve of something ) The public have a rather ambivalent attitude towards science.','cavalier (= very careless, especially about something serious or important ) his cavalier attitude to the truth','patronizing/condescending (= showing that you think you are more important or intelligent than someone ) complaints about patronising attitudes towards women','aggressive/hostile (= showing anger ) Their attitude suddenly became more aggressive.','public attitudes/people’s attitudes Public attitudes have changed.','political attitudes a survey of people’s political attitudes','mental attitude There is a strong connection between health and mental attitude.','somebody’s whole attitude His whole attitude seemed different.','the general attitude His general attitude to our situation was unsympathetic.','have/take/adopt an attitude Not everyone takes a positive attitude towards modern art.','somebody’s attitude changes As you get older, your attitude changes.','an attitude exists This attitude no longer exists in the church.','somebody’s attitude hardens (= they feel less sympathy and they want to be stricter or firmer ) People’s attitudes towards sex offenders have hardened.','an attitude of mind British English (= a way of thinking ) Being young is simply an attitude of mind.','somebody has an attitude problem (= someone is not helpful or pleasant to be with ) Some of the male students have a real attitude problem.']::text[],'[{"sentence":"a coat with attitude","translation":"یک کت با نگرش","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000997326.mp3"}]'::jsonb,1),
('e5fca383-4359-5f2e-8ba3-2acef24a0d56','71e3d273-b99d-5b95-92f7-cac816549126',1,null,null,'spoken & written','a lawyer',null,null,'وکیل دادگستری (به‌ویژه در آمریکا)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('5f7d0a6d-2851-5316-9dba-4388741e337f','322c01c8-c893-5c13-affb-6a8d41ce5cb9',1,null,null,'spoken & written','a group of people who come to watch and listen to someone speaking or performing in public','[ countable ]',null,'مخاطبان، حاضران؛ تماشاگران','{}'::text[],'{}'::text[],array['perform/play to an audience The band played to huge audiences in Mexico City and Buenos Aires.','an audience laughs He has the ability to make an audience laugh.','an audience claps Most of the audience clapped but a few people jeered.','an audience cheers The audience cheered loudly when he came on stage.','the audience boos She swore at the audience and they began to boo her.','a capacity/packed audience (= the largest number of people who can fit into a hall, theatre etc ) The lecture attracted a capacity audience.','an enthusiastic audience They drew enthusiastic audiences at Europe''s biggest rock festival.','stadium audiences Celine Dion''s tour continues to play to sold-out stadium audiences across Europe.']::text[],'[{"sentence":"The audience began clapping and cheering.","translation":"حضار شروع به کف زدن و تشویق کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927443.mp3"},{"sentence":"an audience of 250 business people","translation":"مخاطب 250 تاجر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659681.mp3"},{"sentence":"One member of the audience described the opera as ‘boring’.","translation":"یکی از حضار اپرا را \"خسته کننده\" توصیف کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659682.mp3"}]'::jsonb,3),
('49704b6a-8f64-5c40-bd4e-f3cfb6eb6a8a','322c01c8-c893-5c13-affb-6a8d41ce5cb9',2,null,null,'spoken & written','the people who watch or listen to a particular programme , or who see or hear a particular artist ’s, writer ’s etc work','[ countable also + plural verb ]',null,'افرادی که برنامه خاصی را تماشا یا گوش می دهند، یا کارهای یک هنرمند، نویسنده و غیره خاص را می بینند یا می شنوند.','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The show attracts a regular audience of about 20 million.","translation":"این نمایش حدود 20 میلیون مخاطب ثابت را جذب می کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927447.mp3"},{"sentence":"Goya was one of the first painters to look for a wider audience for his work.","translation":"گویا یکی از اولین نقاشانی بود که به دنبال مخاطبان بیشتری برای آثارش بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659690.mp3"},{"sentence":"The book is not intended for a purely academic audience.","translation":"این کتاب برای مخاطبان صرفاً دانشگاهی در نظر گرفته نشده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001659694.mp3"}]'::jsonb,3),
('141b7d3d-aa89-5e2b-bc2b-e88fc482ba2d','322c01c8-c893-5c13-affb-6a8d41ce5cb9',3,null,null,'spoken & written','a formal meeting with a very important person','[ countable ]',null,'یک ملاقات رسمی با یک شخص بسیار مهم','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was granted an audience with the Pope.","translation":"به او اجازه داده شد تا نزد پاپ شرکت کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000927454.mp3"}]'::jsonb,1),
