('7d7011cb-3948-5b4f-b78f-82fe86356db0','cebeeba1-2d10-5e32-8795-fb81f3f39e54',4,null,null,'literary','the whole universe and all living things','[ uncountable ]',null,'کل جهان و همه موجودات زنده','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('0a550942-9521-5b20-81b6-e0521d0f621f','70f84b60-8f68-5274-8644-f1254040d9ed',1,null,null,'spoken & written','(in the Christian religion ) God''s act of creating the Universe, the Earth , and all living things on Earth. The story of the Creation is told in the book of Genesis in the Bible .',null,null,'(در دین مسیحیت) عمل خدا برای خلق جهان، زمین و همه موجودات زنده روی زمین. داستان آفرینش در کتاب پیدایش در کتاب مقدس بیان شده است.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a7f88e5d-ae4f-5b5d-8690-bc78a92c7e3f','c0f76a2b-1d1f-59be-9acc-61036cd5873c',1,null,null,'spoken & written','involving the use of imagination to produce new ideas or things',null,null,'خلاق، پویا (ایده‌ها)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"This job is so boring. I wish I could do something more creative.","translation":"این کار خیلی کسل کننده است کاش می توانستم کار خلاقانه تری انجام دهم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000845355.mp3"},{"sentence":"I teach creative writing at Trinity College.","translation":"من در کالج ترینیتی نویسندگی خلاق تدریس می کنم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001803281.mp3"},{"sentence":"the creative process of writing a poem","translation":"فرآیند خلاقانه نوشتن یک شعر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001710132.mp3"},{"sentence":"Diaghilev did his great creative work in France.","translation":"دیاگیلف کار خلاقانه بزرگ خود را در فرانسه انجام داد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001710136.mp3"},{"sentence":"a creative solution to the problem","translation":"یک راه حل خلاقانه برای مشکل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000845354.mp3"}]'::jsonb,5),
('acf77a23-be63-5ca0-a0fd-876cfc190dc7','c0f76a2b-1d1f-59be-9acc-61036cd5873c',2,null,null,'spoken & written','someone who is creative is very good at using their imagination to make things',null,null,'کسی که خلاق است در استفاده از تخیل خود برای ساختن چیزها بسیار خوب است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"You’re so creative! I could never make my own clothes.","translation":"تو خیلی خلاقی! من هرگز نتوانستم لباس های خودم را بسازم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000845360.mp3"}]'::jsonb,1),
('7663a4ec-4f46-528c-8dba-caaff8598628','e631d7ea-660a-5a58-a76c-8209cfa2fc1d',1,null,null,'spoken & written','someone such as a writer or artist who uses their imagination or skills to make things',null,null,'کسی مانند نویسنده یا هنرمند که از تخیل یا مهارت های خود برای ساختن چیزها استفاده می کند','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('8dcb1f06-cd97-5ae1-862c-ea7649a6dedf','e0be716c-dbbc-5ee1-9c60-f812473304c5',1,'living thing','موجود زنده','spoken & written','anything that is living, such as an animal , fish , or insect , but not a plant',null,null,'مخلوق، جاندار؛ موجود','{}'::text[],'{}'::text[],array['a living creature The early Greeks believed that plants were living creatures that felt pain and pleasure.','a little/small/tiny creature tiny creatures such as mice','a beautiful/magnificent creature The buffalo is a magnificent creature.','a wild creature Damage to the environment affects all wild creatures.','a sea/marine creature ( also an ocean creature ) The first living creatures were marine creatures.','a furry creature Town dwellers see the squirrel as a cute furry creature, but to farmers they’re a pest.','a dangerous creature dangerous creatures such as tigers','a nocturnal creature (= awake at night and sleeping in the day ) As darkness falls, nocturnal creatures begin to make an appearance.','a primitive/simple creature (= one with only a few cells ) primitive creatures like bacteria','a complex creature (= consisting of many different parts ) Human beings are extremely complex creatures.']::text[],'[{"sentence":"all the living creatures in the sea","translation":"تمام موجودات زنده در دریا","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001710460.mp3"}]'::jsonb,1),
