('d75bd767-4588-5fda-8dc1-40529f180de4','0773cef2-ad76-5371-9ef4-613e5d86b304',1,null,null,'spoken & written','containing or including a lot of information or details',null,null,'مفصل، مشروح؛ با جزئیات','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a detailed study of crime in Seattle","translation":"مطالعه دقیق جنایت در سیاتل","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716247.mp3"},{"sentence":"More detailed information is available on request.","translation":"اطلاعات دقیق تر در صورت درخواست در دسترس است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001716248.mp3"}]'::jsonb,2),
