('fc2d662e-e70f-53b4-988c-0583ce4996e9','b0c53a34-ad22-544c-a221-a71070fb1876',1,null,null,'spoken & written','with no other person, action, process etc between',null,null,'مستقیماً، بی‌واسطه؛ درست رو به','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The new property tax law won’t directly affect us.","translation":"قانون جدید مالیات بر دارایی مستقیماً بر ما تأثیر نخواهد گذاشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145645.mp3"},{"sentence":"We hope to bring together the countries directly involved in the conflict.","translation":"ما امیدواریم که کشورهای درگیر مستقیم در مناقشه را گرد هم بیاوریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145646.mp3"},{"sentence":"Application for admission to this course should be made directly to the University.","translation":"درخواست پذیرش در این دوره باید مستقیماً به دانشگاه ارسال شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695008.mp3"}]'::jsonb,3),
('acc0bc10-0fbf-5574-9e88-d2e6d55971ff','b0c53a34-ad22-544c-a221-a71070fb1876',2,null,null,'spoken & written','exactly in a particular position or direction',null,null,'دقیقا در یک موقعیت یا جهت خاص',array['right']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It was a small house, directly behind the church.","translation":"خانه کوچکی بود، درست پشت کلیسا.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001145651.mp3"},{"sentence":"The girl was sitting directly opposite him.","translation":"دختر درست روبروی او نشسته بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695013.mp3"},{"sentence":"Have you noticed how he never looks directly at you?","translation":"آیا متوجه شده اید که او هرگز مستقیماً به شما نگاه نمی کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001695017.mp3"}]'::jsonb,3),
