('5e5f9747-f532-5b20-b141-462c8be293aa','72df982d-00be-5e63-91dd-b85676fe91cd',1,null,null,'spoken & written','clearly different or belonging to a different type',null,null,'متمایز، مجزا؛ روشن و آشکار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"two entirely distinct languages","translation":"دو زبان کاملاً متمایز","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000808472.mp3"},{"sentence":"There are four distinct types.","translation":"چهار نوع متمایز وجود دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002084563.mp3"},{"sentence":"The learning needs of the two groups are quite distinct from each other.","translation":"نیازهای یادگیری دو گروه کاملاً متمایز از یکدیگر است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829584.mp3"}]'::jsonb,3),
