('77fc8a24-c35a-51d1-888c-6a47cf7f7113','72df982d-00be-5e63-91dd-b85676fe91cd',4,null,null,'spoken & written','a distinct possibility , feeling, quality etc definitely exists and cannot be ignored','[ only before noun ]',null,'یک امکان متمایز، احساس، کیفیت و غیره قطعا وجود دارد و نمی توان آن را نادیده گرفت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I got the distinct impression he was trying to make me angry.","translation":"من این تصور را داشتم که او سعی می‌کرد من را عصبانی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001690354.mp3"},{"sentence":"There is a distinct possibility that this will eventually be needed.","translation":"احتمال مشخصی وجود دارد که در نهایت این مورد نیاز باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829594.mp3"},{"sentence":"a distinct lack of enthusiasm","translation":"فقدان مشخص شور و شوق","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001829597.mp3"}]'::jsonb,3),
('1e74ad07-1272-5ff2-a0d3-6b3648116c78','cf0e72b4-29a3-5fee-a511-276bbeaf7f65',1,null,null,'spoken & written','an area of a town or the countryside , especially one with particular features',null,null,'محله، ناحیه؛ بخش اداری','{}'::text[],'{}'::text[],array['a rural district (= in the countryside ) There are few schools in the rural districts of Bangladesh.','an urban district (= in a town ) In 1911 over three-quarters of the British people lived in urban districts.','the surrounding districts (= in the area around or next to something ) The market attracts farmers from the surrounding district.','a financial/business/commercial district (= where there are a lot of banks and other businesses ) He works in San Francisco’s financial district.','a shopping district The bomb exploded in a crowded shopping district.','an entertainment district (= where there are a lot of bars, clubs etc ) Visitors to Roppongi, Tokyo’s entertainment district, come to experience the latest fashions and have fun.','a theatre district British English , a theater district American English: The restaurant is located in the middle of New York’s theater district.','a residential district (= where people live rather than work ) It is one of Paris’ most exclusive residential districts.','a poor/wealthy district (= where a lot of people are poor/rich ) He lived in one of London’s poorest districts.','a slum district (= where poor people live in very bad conditions ) Rats were running all over the slum districts.','a fashionable district (= popular with rich or well-known people ) Brompton became a fashionable district to live in.']::text[],'[{"sentence":"a house in a pleasant suburban district","translation":"خانه ای در منطقه ای دلپذیر حومه شهر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000809439.mp3"}]'::jsonb,1),
