('c7ca4f82-6645-5f2d-badb-abacea1565ac','926aaa5c-ac84-585e-9175-52fbf0b124e2',1,null,null,'spoken & written','to control someone or something or to have more importance than other people or things','[ intransitive, transitive ]',null,'سلطه داشتن؛ غلبه کردن؛ برتر بودن چشمگیر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The industry is dominated by five multinational companies.","translation":"این صنعت تحت سلطه پنج شرکت چند ملیتی است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000811941.mp3"},{"sentence":"New Orleans dominated throughout the game.","translation":"نیواورلئان در تمام طول بازی تسلط داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702877.mp3"},{"sentence":"Her loud voice totally dominated the conversation.","translation":"صدای بلند او کاملاً بر مکالمه غالب شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001702878.mp3"},{"sentence":"Education issues dominated the election campaign.","translation":"مسائل آموزشی بر مبارزات انتخاباتی غالب بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-002084610.mp3"}]'::jsonb,4),
('a268ab00-2e3f-5374-b31b-3ec8729c2145','926aaa5c-ac84-585e-9175-52fbf0b124e2',2,null,null,'spoken & written','to be larger and more noticeable than anything else in a place','[ transitive ]',null,'بزرگتر و قابل توجه تر از هر چیز دیگری در یک مکان','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The cathedral dominates the city.","translation":"کلیسای جامع بر شهر مسلط است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000811954.mp3"}]'::jsonb,1),
('f6a2a673-0ff0-5788-9485-0fff04c41654','dd70c470-2689-5253-8b06-abde6aaae77d',1,null,null,'spoken & written','to or in the centre or main business area of a town or city',null,null,'به مرکز شهر، مرکز شهر','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I have to go downtown later.","translation":"بعدا باید برم مرکز شهر","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001776975.mp3"}]'::jsonb,1),
('4c45156a-ed1c-5430-9a9b-1bc7d97d9323','111448c6-2f63-51fb-a9cc-736b3120e01e',1,null,null,'spoken & written','great and sudden',null,null,'چشمگیر، به‌شدت (تغییر)؛ نمایشی','{}'::text[],'{}'::text[],array['a dramatic change The Internet has brought dramatic changes to the way we work.','a dramatic increase/rise There has been a dramatic rise in fuel costs.','a dramatic fall/drop/decline Between these years there was a dramatic fall in youth employment.','a dramatic effect/impact An accident can have a dramatic effect on your family’s finances.','a dramatic improvement There has been a dramatic improvement in the standard of students’ work.','a dramatic shift (= change in the way people think or do something ) This announcement signalled a dramatic shift in the government’s policy.','a dramatic result Cameras on the streets have produced dramatic results in reducing crime.','a dramatic difference The programs made a dramatic difference to the lives of millions of people.']::text[],'[{"sentence":"Computers have brought dramatic changes to the workplace.","translation":"کامپیوترها تغییرات شگرفی را در محیط کار ایجاد کرده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000798266.mp3"},{"sentence":"Universities have suffered a dramatic drop in student numbers.","translation":"دانشگاه ها با کاهش چشمگیر تعداد دانشجویان مواجه شده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758297.mp3"},{"sentence":"A serious accident can have a dramatic effect on your family’s finances.","translation":"یک تصادف جدی می تواند تأثیر چشمگیری بر امور مالی خانواده شما داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758300.mp3"}]'::jsonb,3),
('9db8ea77-4544-51f9-8e51-7044a624b40a','111448c6-2f63-51fb-a9cc-736b3120e01e',2,null,null,'spoken & written','exciting or impressive',null,null,'هیجان انگیز یا تاثیرگذار','{}'::text[],'{}'::text[],array['a dramatic change The Internet has brought dramatic changes to the way we work.','a dramatic increase/rise There has been a dramatic rise in fuel costs.','a dramatic fall/drop/decline Between these years there was a dramatic fall in youth employment.','a dramatic effect/impact An accident can have a dramatic effect on your family’s finances.','a dramatic improvement There has been a dramatic improvement in the standard of students’ work.','a dramatic shift (= change in the way people think or do something ) This announcement signalled a dramatic shift in the government’s policy.','a dramatic result Cameras on the streets have produced dramatic results in reducing crime.','a dramatic difference The programs made a dramatic difference to the lives of millions of people.']::text[],'[{"sentence":"A superb goal by Owen earned United a dramatic victory yesterday.","translation":"گل فوق العاده اوون دیروز پیروزی چشمگیری را برای یونایتد به ارمغان آورد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758301.mp3"},{"sentence":"Some of the most dramatic events in American history happened here.","translation":"برخی از دراماتیک ترین وقایع تاریخ آمریکا در اینجا اتفاق افتاد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758302.mp3"},{"sentence":"the dramatic scenery of the Grand Canyon","translation":"مناظر دراماتیک گرند کانیون","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758306.mp3"}]'::jsonb,3),
('51ca0e0e-38d5-5e4a-9b1c-5323e68da9dc','111448c6-2f63-51fb-a9cc-736b3120e01e',3,null,null,'spoken & written','connected with acting or plays',null,null,'مرتبط با بازیگری یا نمایشنامه','{}'::text[],'{}'::text[],array['a dramatic change The Internet has brought dramatic changes to the way we work.','a dramatic increase/rise There has been a dramatic rise in fuel costs.','a dramatic fall/drop/decline Between these years there was a dramatic fall in youth employment.','a dramatic effect/impact An accident can have a dramatic effect on your family’s finances.','a dramatic improvement There has been a dramatic improvement in the standard of students’ work.','a dramatic shift (= change in the way people think or do something ) This announcement signalled a dramatic shift in the government’s policy.','a dramatic result Cameras on the streets have produced dramatic results in reducing crime.','a dramatic difference The programs made a dramatic difference to the lives of millions of people.']::text[],'[{"sentence":"the amateur dramatic society","translation":"جامعه نمایشی آماتور","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-000798274.mp3"},{"sentence":"the dramatic arts","translation":"هنرهای نمایشی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758310.mp3"}]'::jsonb,2),
('b7368b78-71ef-5dc6-a26e-b754abf8b160','111448c6-2f63-51fb-a9cc-736b3120e01e',4,null,null,'spoken & written','intended to be impressive, so that people notice',null,null,'در نظر گرفته شده است که چشمگیر باشد، به طوری که مردم متوجه شوند','{}'::text[],'{}'::text[],array['a dramatic change The Internet has brought dramatic changes to the way we work.','a dramatic increase/rise There has been a dramatic rise in fuel costs.','a dramatic fall/drop/decline Between these years there was a dramatic fall in youth employment.','a dramatic effect/impact An accident can have a dramatic effect on your family’s finances.','a dramatic improvement There has been a dramatic improvement in the standard of students’ work.','a dramatic shift (= change in the way people think or do something ) This announcement signalled a dramatic shift in the government’s policy.','a dramatic result Cameras on the streets have produced dramatic results in reducing crime.','a dramatic difference The programs made a dramatic difference to the lives of millions of people.']::text[],'[{"sentence":"She needed a stunning dress to help her make a dramatic entrance.","translation":"او به یک لباس خیره کننده نیاز داشت تا به او کمک کند تا یک ورودی چشمگیر داشته باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758311.mp3"},{"sentence":"Tristan threw up his hands in a dramatic gesture .","translation":"تریستان با حرکتی دراماتیک دستانش را بالا برد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001758312.mp3"}]'::jsonb,2),
('2bce62c9-cbd6-5b3f-baef-411b563c682d','50f95b5c-5dae-5033-b985-437bf185cae3',1,null,null,'spoken & written','relating to trade , industry , and the management of money','[ only before noun ]',null,'اقتصادی، اقتصادی؛ به‌صرفه','{}'::text[],'{}'::text[],array['economic activity (= the amount of buying, selling etc in a country or area ) This year we have seen an upturn in global economic activity.','economic growth/development (= when businesses become more successful ) We have enjoyed a period of steady economic growth.','an economic slowdown/downturn (= when businesses become less successful ) Experts are predicting an economic slowdown at the beginning of next year.','economic recession (= a period during which a country or area has a lot of problems with its economy ) People are scared they will lose their homes if there is an economic recession.','an economic crisis (= a situation in which there are a lot of problems with the economy, that must be dealt with quickly so the situation does not get worse ) The country’s economic crisis continues to deepen as workers demonstrated against rising food prices.','economic recovery (= the process in which an economic situation improves after a period of failing ) There are now signs of economic recovery in the region.','economic problems The country’s continuing economic problems could lead to recession.','the economic system (= the way in which the economy of a country or area is organized ) There are fears that the country’s whole economic system could collapse.','an economic policy (= the way in which a government manages the economy of a country or area ) Controlling inflation is the main aim of the government’s economic policy.','economic reform (= a set of changes made to an economy in order to improve it ) The government agreed to a programme of economic reform.','the economic climate (= the general economic conditions in a country or area ) In the current economic climate, a lot of people are trying to save more and spend less.','economic sanctions (= laws that stop trade with another country, as a way of forcing its leaders to make political changes ) The UN threatened economic sanctions against the regime.','economic performance (= how well a company, country, or economy is doing ) How do you explain this poor economic performance over the last few years?','economic factor (= a factor involving money or the economy that affects a situation ) Complex economic and social factors have contributed to the rise in violent crime.','an economic indicator (= something that shows how well the economy of a country is doing, and what is likely to happen to it in the future ) The main economic indicators show that the economy is still in decline.']::text[],'[{"sentence":"Economic growth is slow.","translation":"رشد اقتصادی کند است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001180924.mp3"},{"sentence":"the government’s economic policy","translation":"سیاست اقتصادی دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001180925.mp3"},{"sentence":"Economic reform is needed.","translation":"اصلاحات اقتصادی لازم است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001641241.mp3"},{"sentence":"In the current economic climate (= conditions ) , we must keep costs down.","translation":"در شرایط فعلی اقتصادی (= شرایط)، ما باید هزینه ها را پایین نگه داریم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001641242.mp3"}]'::jsonb,4),
('b2d45d24-8db9-5518-815e-c5ce3e0b256a','50f95b5c-5dae-5033-b985-437bf185cae3',2,null,null,'spoken & written','an economic process, activity etc produces enough profit for it to continue',null,null,'یک فرآیند اقتصادی، فعالیت و غیره سود کافی برای ادامه آن تولید می کند',array['profitable']::text[],'{}'::text[],array['economic activity (= the amount of buying, selling etc in a country or area ) This year we have seen an upturn in global economic activity.','economic growth/development (= when businesses become more successful ) We have enjoyed a period of steady economic growth.','an economic slowdown/downturn (= when businesses become less successful ) Experts are predicting an economic slowdown at the beginning of next year.','economic recession (= a period during which a country or area has a lot of problems with its economy ) People are scared they will lose their homes if there is an economic recession.','an economic crisis (= a situation in which there are a lot of problems with the economy, that must be dealt with quickly so the situation does not get worse ) The country’s economic crisis continues to deepen as workers demonstrated against rising food prices.','economic recovery (= the process in which an economic situation improves after a period of failing ) There are now signs of economic recovery in the region.','economic problems The country’s continuing economic problems could lead to recession.','the economic system (= the way in which the economy of a country or area is organized ) There are fears that the country’s whole economic system could collapse.','an economic policy (= the way in which a government manages the economy of a country or area ) Controlling inflation is the main aim of the government’s economic policy.','economic reform (= a set of changes made to an economy in order to improve it ) The government agreed to a programme of economic reform.','the economic climate (= the general economic conditions in a country or area ) In the current economic climate, a lot of people are trying to save more and spend less.','economic sanctions (= laws that stop trade with another country, as a way of forcing its leaders to make political changes ) The UN threatened economic sanctions against the regime.','economic performance (= how well a company, country, or economy is doing ) How do you explain this poor economic performance over the last few years?','economic factor (= a factor involving money or the economy that affects a situation ) Complex economic and social factors have contributed to the rise in violent crime.','an economic indicator (= something that shows how well the economy of a country is doing, and what is likely to happen to it in the future ) The main economic indicators show that the economy is still in decline.']::text[],'[{"sentence":"It is no longer economic to run the service.","translation":"اجرای سرویس دیگر اقتصادی نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001180934.mp3"}]'::jsonb,1),
('bacba332-e6e1-5948-ab2b-9fa138db112c','6d9dba39-6a28-5daf-a262-1b7952ddf5e6',1,null,null,'spoken & written','when people vote to choose someone for an official position','[ countable ]',null,'انتخابات','{}'::text[],'{}'::text[],array['have/hold an election The government plans to hold an election in November.','call an election (= arrange for an election to happen ) The prime minister would be unwise to call an election now.','win an election Who do you think will win the election?','lose an election If the party loses the election, they may decide they need a new leader.','fight an election British English ( also contest an election British English formal ) (= take part in it and try to win ) Three independent candidates are also planning to contest the election.','run for election ( also stand for election British English ) (= try to become elected ) If you plan to stand for election to the committee, you must be nominated by three members.','rig an election (= dishonestly arrange the result ) He accused the ruling party of rigging the elections.','boycott an election (= refuse to take part in an election as a protest ) Opposition parties have threatened to boycott the elections.','fair (= with no unfair advantage to one person or group ) The ruling party has promised that the elections will be fair.','free (= with everyone allowed to vote for who they want ) These will be the country’s first free multi-party elections.','democratic The unions are calling for democratic elections.','a general/national election (= one in which the whole country votes to elect a government ) Labour’s victory in the general election gave them a huge majority.','a local/regional election The Green Party increased its share of the vote in the French regional elections.','a presidential election (= to elect a new president ) He is the Democrat Party’s candidate for the next presidential election.','a leadership election (= to elect a new leader for a political party ) The result of the leadership election will be announced today.','a congressional/parliamentary election (= to elect people to a congress or parliament ) People voted overwhelmingly Republican in the last congressional elections.','a federal election (= to elect a federal government ) The federal elections are scheduled for May 2.','a mayoral election (= to elect a new mayor ) The mayoral elections are due to take place next month.','a gubernatorial election (= one to elect a governor ) We are still waiting for the result of the gubernatorial election in New Jersey.','an election victory/defeat He became prime minister after a decisive election victory.','the election results The election results have been coming in all night.','an election campaign The election campaign got off to a bad start.','an election candidate British English (= someone trying to be elected in an election ) Local party members choose the election candidates.','an election promise/pledge (= one that is made while a person or party is trying to be elected ) The government has broken all its election promises.','an election broadcast British English (= a programme by a party saying why people should vote for them in an election ) a Conservative Party election broadcast','an election rally (= a public meeting to support a politician or party before an election ) He drove to Paris to address an election rally.','an election year (= a year in which there is an election ) The Chancellor won’t raise taxes in an election year.','election day/night (= the day or night when people are voting and the votes are being counted ) We urge all our supporters to get out and vote on election night.','election time I’m sick of all those political pamphlets that come through my door at election time.','the run-up to the election (= the period of time before an election ) There have been violent street protests in the run-up to the elections.']::text[],'[{"sentence":"The Labour Party won the 2001 election by a huge majority.","translation":"حزب کارگر در انتخابات سال 2001 با اکثریت عظیمی پیروز شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001183624.mp3"},{"sentence":"Elections for the state governorship will be on November 25.","translation":"انتخابات فرمانداری ایالتی در 25 نوامبر برگزار می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000511.mp3"}]'::jsonb,2),
('d82f5118-519a-58c9-ab6c-1b7f5609a6a6','6d9dba39-6a28-5daf-a262-1b7952ddf5e6',2,null,null,'spoken & written','the fact of being elected to an official position','[ singular ]',null,'حقیقت انتخاب شدن به یک مقام رسمی','{}'::text[],'{}'::text[],array['have/hold an election The government plans to hold an election in November.','call an election (= arrange for an election to happen ) The prime minister would be unwise to call an election now.','win an election Who do you think will win the election?','lose an election If the party loses the election, they may decide they need a new leader.','fight an election British English ( also contest an election British English formal ) (= take part in it and try to win ) Three independent candidates are also planning to contest the election.','run for election ( also stand for election British English ) (= try to become elected ) If you plan to stand for election to the committee, you must be nominated by three members.','rig an election (= dishonestly arrange the result ) He accused the ruling party of rigging the elections.','boycott an election (= refuse to take part in an election as a protest ) Opposition parties have threatened to boycott the elections.','fair (= with no unfair advantage to one person or group ) The ruling party has promised that the elections will be fair.','free (= with everyone allowed to vote for who they want ) These will be the country’s first free multi-party elections.','democratic The unions are calling for democratic elections.','a general/national election (= one in which the whole country votes to elect a government ) Labour’s victory in the general election gave them a huge majority.','a local/regional election The Green Party increased its share of the vote in the French regional elections.','a presidential election (= to elect a new president ) He is the Democrat Party’s candidate for the next presidential election.','a leadership election (= to elect a new leader for a political party ) The result of the leadership election will be announced today.','a congressional/parliamentary election (= to elect people to a congress or parliament ) People voted overwhelmingly Republican in the last congressional elections.','a federal election (= to elect a federal government ) The federal elections are scheduled for May 2.','a mayoral election (= to elect a new mayor ) The mayoral elections are due to take place next month.','a gubernatorial election (= one to elect a governor ) We are still waiting for the result of the gubernatorial election in New Jersey.','an election victory/defeat He became prime minister after a decisive election victory.','the election results The election results have been coming in all night.','an election campaign The election campaign got off to a bad start.','an election candidate British English (= someone trying to be elected in an election ) Local party members choose the election candidates.','an election promise/pledge (= one that is made while a person or party is trying to be elected ) The government has broken all its election promises.','an election broadcast British English (= a programme by a party saying why people should vote for them in an election ) a Conservative Party election broadcast','an election rally (= a public meeting to support a politician or party before an election ) He drove to Paris to address an election rally.','an election year (= a year in which there is an election ) The Chancellor won’t raise taxes in an election year.','election day/night (= the day or night when people are voting and the votes are being counted ) We urge all our supporters to get out and vote on election night.','election time I’m sick of all those political pamphlets that come through my door at election time.','the run-up to the election (= the period of time before an election ) There have been violent street protests in the run-up to the elections.']::text[],'[{"sentence":"Within three months of his election he was forced to resign.","translation":"در عرض سه ماه پس از انتخاب او مجبور به استعفا شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001183629.mp3"},{"sentence":"his election to Parliament","translation":"انتخاب او به مجلس","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629468.mp3"}]'::jsonb,2),
('b9507f70-356a-59d6-9ec9-1b9a3ad42817','6a314b0d-45e2-5c1c-a165-27df9751142b',1,null,null,'spoken & written','needing electricity to work, produced by electricity, or used for carrying electricity',null,null,'برقی، الکتریکی؛ برق‌دار','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"the heat from a small electric fire","translation":"گرمای حاصل از یک آتش سوزی کوچک الکتریکی","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001832419.mp3"},{"sentence":"an electric blanket (= one with electric wires in it, used for making a bed warm )","translation":"پتوی برقی (= پتوی با سیم های برق که برای گرم کردن تخت استفاده می شود)","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629499.mp3"}]'::jsonb,2),
('c2dca96e-0e27-5403-8d9d-5c20712b2728','6a314b0d-45e2-5c1c-a165-27df9751142b',2,null,null,'spoken & written','making people feel very excited',null,null,'باعث می شود مردم احساس هیجان زیادی کنند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The atmosphere in the courtroom was electric .","translation":"فضای دادگاه برق بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001183771.mp3"}]'::jsonb,1),
('996f5d51-7709-5bdc-9602-c346c11b9ba0','42c28eda-c0be-5c3d-9e26-12f40967df53',1,null,null,'spoken & written','a machine that takes people and goods from one level to another in a building',null,null,'آسانسور (آمریکایی)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We’ll have to take the elevator.","translation":"باید سوار آسانسور شویم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001629627.mp3"}]'::jsonb,1),
('73d97b1f-3ada-5d35-a495-c64ed45e6232','42c28eda-c0be-5c3d-9e26-12f40967df53',2,null,null,'spoken & written','a machine with a moving belt and containers , used for lifting grain and liquids , or for taking things off ships',null,null,'ماشینی با تسمه متحرک و ظروف که برای بلند کردن غلات و مایعات یا برای برداشتن وسایل از کشتی استفاده می شود.','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('a2d162d2-cc04-58ab-9d37-0bc911479c14','d72ef1ec-5ec1-53d6-837c-e6ad945f3935',1,null,null,'spoken & written','special attention or importance',null,null,'تأکید، برجستگی؛ اهمیت ویژه','{}'::text[],'{}'::text[],array['put emphasis on something We need to put greater emphasis on planning. The airline is accused of placing more emphasis on profit than on safety.','place/lay emphasis on something formal The coach has placed the emphasis firmly on youth by including three teenagers in the team.','give emphasis to something Since league tables were introduced, schools have given even greater emphasis to exam results.','shift the emphasis (= change the emphasis to something else ) With drug addicts, we need to shift the emphasis from punishment to treatment.','add emphasis (= make an opinion or fact seem more important ) Put bullet points before each statement to add emphasis.','the emphasis shifts/moves (= changes ) The emphasis is now shifting away from oil towards renewable sources of energy.','great emphasis The company places great emphasis on customer care.','a strong/heavy emphasis There is a strong emphasis on research in the university.','the main emphasis The main emphasis must be on quality, not quantity.','particular/special emphasis The new legislation places particular emphasis on energy conservation.','increased/increasing emphasis Recently, there has been an increasing emphasis on creating more jobs.','considerable emphasis Most religions put considerable emphasis on the importance of marriage.','a change of emphasis ( also a shift in emphasis ) There has been a change of emphasis in the government’s foreign policy.']::text[],'[{"sentence":"In Japan there is a lot of emphasis on politeness.","translation":"در ژاپن بر ادب تاکید زیادی می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646246.mp3"},{"sentence":"The course places emphasis on practical work.","translation":"این دوره بر کار عملی تأکید دارد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646249.mp3"},{"sentence":"a change of emphasis in government policy","translation":"تغییر تاکید در سیاست دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646250.mp3"}]'::jsonb,3),
('b89b2970-773d-53ea-acbb-2f0fa08cacc0','d72ef1ec-5ec1-53d6-837c-e6ad945f3935',2,null,null,'spoken & written','special importance that is given to a word or phrase by saying it louder or higher, or by printing it in a special way',null,null,'اهمیت ویژه ای که به یک کلمه یا عبارت با بلندتر یا بلندتر گفتن یا با چاپ کردن آن به شکل خاص داده می شود.','{}'::text[],'{}'::text[],array['put emphasis on something We need to put greater emphasis on planning. The airline is accused of placing more emphasis on profit than on safety.','place/lay emphasis on something formal The coach has placed the emphasis firmly on youth by including three teenagers in the team.','give emphasis to something Since league tables were introduced, schools have given even greater emphasis to exam results.','shift the emphasis (= change the emphasis to something else ) With drug addicts, we need to shift the emphasis from punishment to treatment.','add emphasis (= make an opinion or fact seem more important ) Put bullet points before each statement to add emphasis.','the emphasis shifts/moves (= changes ) The emphasis is now shifting away from oil towards renewable sources of energy.','great emphasis The company places great emphasis on customer care.','a strong/heavy emphasis There is a strong emphasis on research in the university.','the main emphasis The main emphasis must be on quality, not quantity.','particular/special emphasis The new legislation places particular emphasis on energy conservation.','increased/increasing emphasis Recently, there has been an increasing emphasis on creating more jobs.','considerable emphasis Most religions put considerable emphasis on the importance of marriage.','a change of emphasis ( also a shift in emphasis ) There has been a change of emphasis in the government’s foreign policy.']::text[],'[{"sentence":"The emphasis should be on the first syllable.","translation":"تاکید باید روی هجای اول باشد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001186820.mp3"},{"sentence":"‘And I can assure you, ’ she said with emphasis , ‘that he is innocent.’","translation":"او با تاکید گفت: \"و من می توانم به شما اطمینان دهم که او بی گناه است.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001646256.mp3"}]'::jsonb,2),
('aacb5e8b-7d2c-54c7-9296-c04a775a1ef7','fe71ab66-0414-56f2-9b7a-08235f926e95',1,null,null,'spoken & written','someone who is paid to work for someone else',null,null,'کارمند، استخدام‌شده',array['worker']::text[],'{}'::text[],array['a full-time/part-time employee We now have 110 full-time employees.','a permanent/temporary employee Some of the temporary employees were later hired as permanent staff.','a senior/junior employee The company also offers substantial bonuses to senior employees.','a male/female employee The majority of the female employees are under 30.','a former employee The company is being sued by three former employees.','a retired employee They are for an increase in pension payments to retired employees.','have employees The Birmingham-based company has over 200 employees.','recruit employees (= offer them jobs ) We are recruiting employees for our IT division.','lay off employees (= stop employing them because there is no work for them to do ) Unions fear that many part-time employees will be laid off.','make employees redundant (= stop employing them because there is no work for them to do ) Crossways was nearing bankruptcy and had to make 720 employees redundant.','dismiss/sack an employee (= stop employing them because they have behaved badly or broken a rule ) Seven employees were dismissed for misconduct.','an employee joins a company/firm etc Employees who join the firm after April receive a percentage of the annual bonus.','an employee leaves When a senior employee leaves the company, we hold an exit interview.']::text[],'[{"sentence":"a government employee","translation":"یک کارمند دولت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001645884.mp3"}]'::jsonb,1),
('a0d59801-8522-5cde-9730-302d7d368044','cce3ff8d-aa88-582a-a406-afc2989ae41e',1,null,null,'spoken & written','a person, company, or organization that employs people',null,null,'کارفرما، بهره‌بردار (کار)؛ کارفرما (شرکت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The shoe factory is the largest employer in this area.","translation":"کارخانه کفش بزرگترین کارفرما در این زمینه است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001187980.mp3"}]'::jsonb,1),
('18cf5471-5c5d-5136-a95f-3cb918b0c570','573c10a8-8ad9-505b-8d45-f7776c4c6c37',1,null,null,'spoken & written','someone whose job is to design or build roads , bridges , machines etc',null,null,'مهندس؛ تدبیر کردن (تلاش برای)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He trained as a civil engineer (= one who designs and builds roads, bridges etc ) .","translation":"او به عنوان یک مهندس عمران (= کسی که جاده ها، پل ها و غیره را طراحی و می سازد) آموزش دید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001831957.mp3"}]'::jsonb,1),
