('9a838c89-5261-5b9e-ad05-29f60c8d545d','166c7404-8a94-52a3-afe4-d34036b0a22f',1,null,null,'spoken & written','to make something happen by skilful secret planning',null,null,'با برنامه ریزی مخفیانه ماهرانه چیزی را رقم بزند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"powerful enemies who engineered his downfall","translation":"دشمنان قدرتمندی که سقوط او را مهندسی کردند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001193825.mp3"},{"sentence":"Perhaps she could engineer a meeting between them?","translation":"شاید او بتواند یک ملاقات بین آنها را مهندسی کند؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001678583.mp3"}]'::jsonb,2),
