('46d8f773-2872-53a5-9b77-4fa954dd4b92','def4c992-ffdf-59c6-9712-7435c4348e63',1,null,null,'spoken & written','very big in size or in amount',null,null,'عظیم، بسیار بزرگ؛ هولناک (پیشرفت)',array['huge']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"an enormous bunch of flowers","translation":"یک دسته گل بزرگ","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196005.mp3"},{"sentence":"an enormous amount of money","translation":"مقدار زیادی پول","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001196006.mp3"},{"sentence":"The team made an enormous effort .","translation":"تیم تلاش زیادی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001678750.mp3"},{"sentence":"Their garden is absolutely enormous.","translation":"باغ آنها کاملاً عظیم است.","audio_url":null}]'::jsonb,4),
('27951f66-2fe6-5c69-9703-bd6666d8257b','1dad3378-5a54-5c69-b07b-3f4a6a43a683',1,null,null,'spoken & written','completely and in every possible way',null,null,'کاملاً، تماماً؛ به هر جهت','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Our situation is entirely different.","translation":"شرایط ما کاملا متفاوت است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001498477.mp3"},{"sentence":"The ridge consists entirely of volcanic rock.","translation":"این خط الراس کاملاً از سنگ های آتشفشانی تشکیل شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001498478.mp3"},{"sentence":"Her reasons were not entirely clear.","translation":"دلایل او کاملاً روشن نبود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625755.mp3"}]'::jsonb,3),
('7107707a-b5f5-5f75-8974-88519f2b31d7','3eb4c1ff-bad2-5a19-ac88-58cd325905df',1,null,null,'spoken & written','a door, gate etc that you go through to enter a place','[ countable ]',null,'ورودی، در ورودی؛ ورود (جسورانه)؛ ورودی (دانشگاه)','{}'::text[],'{}'::text[],array['the main entrance She found a parking space close to the hospital''s main entrance.','the front/back/rear/side entrance There is a long drive with steps leading to the front entrance.','a narrow entrance I could see part of the yard through the narrow entrance.','a wide entrance There was a wide entrance at the front of the building.','the hotel/hospital/museum etc entrance Our taxi pulled up outside the hotel entrance.','the harbour entrance British English , the harbor entrance American English We watched as the ferry approached the harbour entrance.','the tunnel entrance At high tide, the tunnel entrance is totally submerged.','come/go/pass etc through an entrance People passed in single file through the narrow entrance.','use an entrance It''s quicker to use the side entrance.','block an entrance A large stone blocked the entrance to the tomb.','an entrance hall (= a room at the entrance to a building ) He walked through the front door into the entrance hall.','an entrance lobby/foyer (= an area at the entrance to a large building ) There was no sign of her in the entrance foyer.','an entrance gate/door Soldiers were guarding the entrance gate.']::text[],'[{"sentence":"the main entrance to the school","translation":"ورودی اصلی مدرسه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001499737.mp3"},{"sentence":"the station entrance","translation":"ورودی ایستگاه","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625420.mp3"}]'::jsonb,2),
('26d0c9bd-c5ed-5422-9b74-b7bbae5f6fcd','3eb4c1ff-bad2-5a19-ac88-58cd325905df',2,null,null,'spoken & written','the act of entering a place or room, especially in a way that people notice','[ countable usually singular ]',null,'عمل ورود به یک مکان یا اتاق، به ویژه به نحوی که مردم متوجه آن شوند','{}'::text[],'{}'::text[],array['the main entrance She found a parking space close to the hospital''s main entrance.','the front/back/rear/side entrance There is a long drive with steps leading to the front entrance.','a narrow entrance I could see part of the yard through the narrow entrance.','a wide entrance There was a wide entrance at the front of the building.','the hotel/hospital/museum etc entrance Our taxi pulled up outside the hotel entrance.','the harbour entrance British English , the harbor entrance American English We watched as the ferry approached the harbour entrance.','the tunnel entrance At high tide, the tunnel entrance is totally submerged.','come/go/pass etc through an entrance People passed in single file through the narrow entrance.','use an entrance It''s quicker to use the side entrance.','block an entrance A large stone blocked the entrance to the tomb.','an entrance hall (= a room at the entrance to a building ) He walked through the front door into the entrance hall.','an entrance lobby/foyer (= an area at the entrance to a large building ) There was no sign of her in the entrance foyer.','an entrance gate/door Soldiers were guarding the entrance gate.']::text[],'[{"sentence":"Bridget made a dramatic entrance into the room.","translation":"بریجت وارد اتاق شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001625423.mp3"}]'::jsonb,1),
