('4d3b03e8-99aa-5126-96c4-8e756f091a9b','71838fd9-dbb5-506e-9aed-f24f30ea0d5f',1,null,null,'spoken & written','to give someone something and receive the same kind of thing from them at the same time',null,null,'دادن چیزی به کسی و در عین حال همان چیزی را از او دریافت می کند',array['change']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We exchange gifts at Christmas.","translation":"ما در کریسمس هدایایی رد و بدل می کنیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001226685.mp3"},{"sentence":"At the end of the game, players traditionally exchange shirts with each other.","translation":"در پایان بازی، بازیکنان به طور سنتی پیراهن های خود را با یکدیگر تعویض می کنند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001226686.mp3"},{"sentence":"We exchanged phone numbers.","translation":"شماره تلفن ها را رد و بدل کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001735119.mp3"},{"sentence":"Where can I exchange my dollars for pounds?","translation":"کجا می توانم دلارم را با پوند عوض کنم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001226697.mp3"},{"sentence":"Do you want to swap (British English) / trade (American English) seats with me?","translation":"آیا می‌خواهید صندلی‌های (انگلیسی انگلیسی) یا (انگلیسی آمریکایی) را با من عوض کنید؟","audio_url":null}]'::jsonb,5),
('c25bf3c3-8803-5003-8727-4e832ab0c30b','71838fd9-dbb5-506e-9aed-f24f30ea0d5f',2,null,null,'spoken & written','to replace one thing with another',null,null,'برای جایگزینی یک چیز با چیز دیگر',array['swap']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He exchanged the black jacket for a blue one.","translation":"کت مشکی را با کت آبی عوض کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001735127.mp3"}]'::jsonb,1),
