('e102a2bb-25a9-5b7a-a210-4570bb20c0df','f18ecd2e-bfec-5f6c-93aa-957262da4c2e',2,null,null,'spoken & written',null,null,'don’t hesitate to do something','تردید کردن، درنگ کردن (پیش از گفتن)','{}'::text[],'{}'::text[],'{}'::text[],'[]'::jsonb,0),
('6922293f-7a05-5bc5-8cdf-9d076a0f2239','cd85e973-f37e-501b-8072-580bec663e95',1,null,null,'spoken & written','work that a student at school is asked to do at home',null,null,'تکلیف، مشق شب','{}'::text[],'{}'::text[],array['do your homework Paul, have you done your homework?','give (somebody) homework ( also set (somebody) homework British English ) The teacher gave them some homework to do by Monday.','help somebody with their homework I often have to help her with her homework.','hand in your homework (= give it to the teacher ) You must hand in your homework by Friday.','start/finish your homework You’re not going out until you’ve finished your homework.','hand in your homework (= give homework you have done to your teacher ) He always hands his homework in on time.','biology/history/French etc homework The science homework was really hard.','a piece of homework I still have one piece of homework left to do.']::text[],'[{"sentence":"For homework , finish the exercise on page 14.","translation":"برای انجام تکالیف، تمرین صفحه 14 را تمام کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000790.mp3"}]'::jsonb,1),
('2b848fa9-7da1-5d31-a882-dd19bf3e28f4','cd85e973-f37e-501b-8072-580bec663e95',2,null,null,'spoken & written','if you do your homework, you prepare for an important activity by finding out information you need',null,null,'اگر تکالیف خود را انجام دهید، با یافتن اطلاعات مورد نیاز خود را برای یک فعالیت مهم آماده می کنید','{}'::text[],'{}'::text[],array['do your homework Paul, have you done your homework?','give (somebody) homework ( also set (somebody) homework British English ) The teacher gave them some homework to do by Monday.','help somebody with their homework I often have to help her with her homework.','hand in your homework (= give it to the teacher ) You must hand in your homework by Friday.','start/finish your homework You’re not going out until you’ve finished your homework.','hand in your homework (= give homework you have done to your teacher ) He always hands his homework in on time.','biology/history/French etc homework The science homework was really hard.','a piece of homework I still have one piece of homework left to do.']::text[],'[{"sentence":"It’s worth doing a bit of homework before buying a computer.","translation":"ارزش آن را دارد که قبل از خرید کامپیوتر کمی تکالیف را انجام دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745194.mp3"}]'::jsonb,1),
('acd8d602-0bed-50f3-b925-a38115d00703','863e1fc8-4c33-5a52-83ce-47a9a5dc9218',1,null,null,'spoken & written','used to emphasize that what you are saying is true , even though it may seem surprising',null,null,'راستش، به‌راستی؛ صادقانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I honestly don’t know how old my parents are.","translation":"راستش نمی دانم پدر و مادرم چند سال دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745256.mp3"},{"sentence":"I can honestly say that I never worry about him now.","translation":"به صراحت می توانم بگویم که در حال حاضر هرگز نگران او نیستم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745257.mp3"}]'::jsonb,2),
('ea8514be-c40e-5f07-9b49-edd364d4e2e7','863e1fc8-4c33-5a52-83ce-47a9a5dc9218',2,null,null,'spoken','used when you are shocked or annoyed by something someone has said or done',null,null,'زمانی استفاده می شود که از چیزی که کسی گفته یا انجام داده است شوکه یا آزرده خاطر می شوید',array['really']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Honestly! Do you ever listen?","translation":"انصافا! آیا تا به حال گوش می دهید؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001358092.mp3"}]'::jsonb,1),
('e434177f-67bf-557d-8158-d540ba2df960','863e1fc8-4c33-5a52-83ce-47a9a5dc9218',3,null,null,'spoken','used to try to make someone believe that what you have just said is true',null,null,'سعی می‌کردم کسی را باور کند که آنچه شما گفتید درست است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"It wasn’t me, honestly!","translation":"راستش من نبودم!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001358097.mp3"}]'::jsonb,1),
('53bcebd5-a3e4-5072-a7c9-c9a71176b920','863e1fc8-4c33-5a52-83ce-47a9a5dc9218',4,null,null,'spoken & written','in an honest way',null,null,'به روشی صادقانه',array['truthfully']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Tell me honestly, Kate, what do you think of John?","translation":"صادقانه به من بگو کیت، نظرت در مورد جان چیست؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745260.mp3"},{"sentence":"We talked openly and honestly.","translation":"ما صریح و صادقانه صحبت کردیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745261.mp3"},{"sentence":"‘No, I don’t, ’ she answered honestly.","translation":"او صادقانه پاسخ داد: \"نه، من نمی دانم.\"","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001358081.mp3"}]'::jsonb,3),
('97243c21-5fef-55bc-8036-0a4dd6a346a1','a22fca6c-35dd-51a8-8d6e-995e03213041',1,null,null,'spoken & written','if something that you try to do is hopeless, there is no possibility of it being successful',null,null,'بی‌امید، ناامیدکننده؛ بی‌چاره (بی‌منفعت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"We tried to stop the flames from spreading, but we knew it was hopeless.","translation":"ما سعی کردیم از گسترش شعله جلوگیری کنیم، اما می دانستیم که ناامیدکننده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360336.mp3"},{"sentence":"Getting your work published often seems a hopeless task .","translation":"انتشار کار شما اغلب کار ناامیدکننده ای به نظر می رسد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745707.mp3"},{"sentence":"I kept on struggling forward, even though I knew it was hopeless .","translation":"من به مبارزه رو به جلو ادامه دادم، حتی اگر می دانستم ناامیدکننده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001807493.mp3"}]'::jsonb,3),
('0b0abc84-b222-5385-ae0e-436b8e18f187','a22fca6c-35dd-51a8-8d6e-995e03213041',2,null,null,'spoken & written','a hopeless situation is so bad that there is no chance of success or improvement',null,null,'وضعیت ناامید کننده آنقدر بد است که هیچ شانسی برای موفقیت یا بهبود وجود ندارد','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The situation is not as hopeless as it might seem.","translation":"وضعیت آنقدرها هم که به نظر می رسد ناامیدکننده نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745711.mp3"},{"sentence":"the millions who live in hopeless poverty","translation":"میلیون ها نفری که در فقر ناامیدکننده زندگی می کنند","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745712.mp3"}]'::jsonb,2),
('cca57436-9b2d-5617-b5fb-a19abf371df1','a22fca6c-35dd-51a8-8d6e-995e03213041',3,null,null,'informal','very bad',null,null,'خیلی بد',array['terrible']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I’m a hopeless cook.","translation":"من آشپزی ناامید هستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360342.mp3"},{"sentence":"My brother was always pretty hopeless at ball games.","translation":"برادرم همیشه در بازی های توپ ناامید بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745717.mp3"},{"sentence":"I’m hopeless with machinery.","translation":"من از ماشین آلات ناامید هستم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745720.mp3"},{"sentence":"I’ve got a hopeless memory.","translation":"خاطره ناامید کننده ای دارم","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745721.mp3"},{"sentence":"The public transport system was absolutely hopeless.","translation":"سیستم حمل و نقل عمومی کاملاً ناامید کننده بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745722.mp3"}]'::jsonb,5),
('a2b4437f-5cb7-5e2a-b730-6e826b69e10d','a22fca6c-35dd-51a8-8d6e-995e03213041',4,null,null,'spoken & written','feeling no hope',null,null,'احساس بی امیدی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"I began to feel lonely and hopeless.","translation":"شروع کردم به احساس تنهایی و ناامیدی.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745723.mp3"}]'::jsonb,1),
('a9596232-075d-5552-942a-0fe05eae8ed4','a22fca6c-35dd-51a8-8d6e-995e03213041',5,null,null,'spoken & written','used, often humorously, to say that someone’s bad behaviour cannot be changed',null,null,'اغلب به صورت طنز برای گفتن اینکه رفتار بد کسی قابل تغییر نیست استفاده می شود','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Oh, James, you really are a hopeless case (= it seems impossible to change your behaviour ) !","translation":"آه، جیمز، تو واقعاً یک مورد ناامید هستی (= تغییر رفتارت غیرممکن به نظر می رسد)!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360355.mp3"},{"sentence":"She was a hopeless romantic, always convinced that one day she would meet the man of her dreams.","translation":"او یک رمانتیک ناامید بود، همیشه متقاعد شده بود که روزی مرد رویاهایش را ملاقات خواهد کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001745731.mp3"}]'::jsonb,2),
('61492f1d-63a8-560c-8f2c-5fe550b7d5ac','23b21f5a-c541-50bf-b499-3ee7e761c6c5',1,null,null,'spoken & written','very bad – used, for example , about things you see, taste , or smell , or about the weather',null,null,'خیلی بد، فجیع؛ نفرت‌انگیز (طعم)؛ فرسنگ (زمان)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The weather has been really horrible all week.","translation":"هوا در تمام هفته واقعا وحشتناک بوده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360785.mp3"},{"sentence":"a horrible smell","translation":"یک بوی وحشتناک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001980828.mp3"},{"sentence":"The food looked horrible, but it tasted OK.","translation":"غذا وحشتناک به نظر می رسید، اما طعم خوبی داشت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001728704.mp3"}]'::jsonb,3),
('6716b368-03a2-5070-aa13-cf91356d0b78','23b21f5a-c541-50bf-b499-3ee7e761c6c5',2,null,null,'spoken & written','very unpleasant and often frightening , worrying , or upsetting',null,null,'بسیار ناخوشایند و اغلب ترسناک، نگران کننده یا ناراحت کننده است','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"a horrible dream","translation":"یک رویای وحشتناک","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360780.mp3"},{"sentence":"I have a horrible feeling that we’re going to miss the plane.","translation":"احساس وحشتناکی دارم که هواپیما را از دست می دهیم.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001980829.mp3"}]'::jsonb,2),
('48b7b672-b931-5247-9438-29de81f819d9','23b21f5a-c541-50bf-b499-3ee7e761c6c5',3,null,null,'spoken & written','rude and unfriendly',null,null,'بی ادب و غیر دوستانه','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"She’s a horrible person.","translation":"او یک فرد وحشتناک است","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001360791.mp3"},{"sentence":"What a horrible thing to say!","translation":"چه چیز وحشتناکی گفتن!","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001980832.mp3"},{"sentence":"Why are you so horrible to me?","translation":"چرا اینقدر برای من وحشتناکی؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001728705.mp3"}]'::jsonb,3),
('f04777dc-e476-5e71-bfe8-990708a5e30d','a9bff660-ddb9-5668-9a21-51d16ce5310f',1,null,null,'spoken & written','a large building where sick or injured people receive medical treatment',null,null,'بیمارستان، شفاخانه','{}'::text[],'{}'::text[],array['go to hospital British English , go to the hospital American English The pain got worse and she had to go to the hospital.','be taken/rushed/airlifted to hospital British English , be taken/rushed/airlifted to the hospital American English Three people were taken to hospital after a crash on the motorway.','be admitted to hospital British English , be admitted to the hospital American English He was admitted to hospital suffering from chest pain.','leave/come out of hospital British English , leave/come out of the hospital American English Her mother never left the hospital.','be discharged/released from hospital British English , be discharged/released from the hospital American English (= be allowed to leave a hospital because you are better ) It was several weeks before he was released from hospital.','a psychiatric hospital ( also a mental hospital old-fashioned ) (= for people with mental illnesses ) He was admitted to a secure psychiatric hospital.','a children’s hospital an important children’s hospital','a maternity hospital British English (= for women having babies ) Many maternity hospitals have been forced to close.','hospital treatment/care What do older people think of hospital care?','a hospital stay (= the period someone spends in hospital ) New surgical techniques mean a hospital stay of less than 48 hours.','a hospital bed There is a shortage of hospital beds.','a hospital ward/room nurses working on hospital wards']::text[],'[{"sentence":"They are building a new hospital.","translation":"آنها در حال ساخت یک بیمارستان جدید هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000793.mp3"},{"sentence":"She visited him in hospital.","translation":"او را در بیمارستان ملاقات کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000794.mp3"},{"sentence":"Two people are in the hospital with serious burns.","translation":"دو نفر با سوختگی شدید در بیمارستان بستری هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000795.mp3"}]'::jsonb,3),
('a4f1c3c9-c751-533b-8250-d071bbdfaa80','820145c6-245e-5def-8ea6-f9057328ab32',1,null,null,'spoken & written','to recognize and correctly name someone or something',null,null,'شناسایی کردن، تشخیص دادن؛ پیوند دادن (خود)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"He was too far away to be able to identify faces.","translation":"او خیلی دور بود که نمی توانست چهره ها را شناسایی کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750181.mp3"},{"sentence":"The police took fingerprints and identified the body .","translation":"پلیس اثر انگشت گرفت و جسد را شناسایی کرد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001398288.mp3"},{"sentence":"Eyewitnesses identified the gunman as an army sergeant.","translation":"شاهدان عینی مرد مسلح را یک گروهبان ارتش معرفی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001398291.mp3"},{"sentence":"The aircraft were identified as American.","translation":"این هواپیما آمریکایی بود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750185.mp3"}]'::jsonb,4),
('6e9f453e-78a0-5ecc-918f-45b30f3b0965','820145c6-245e-5def-8ea6-f9057328ab32',2,null,null,'spoken & written','to recognize something or discover exactly what it is, what its nature or origin is etc',null,null,'تشخیص دادن چیزی یا کشف اینکه دقیقاً چیست، ماهیت یا منشأ آن چیست و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Scientists have identified the gene that causes abnormal growth.","translation":"دانشمندان ژنی را شناسایی کرده اند که باعث رشد غیر طبیعی می شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001398296.mp3"},{"sentence":"They identified a number of problem areas.","translation":"آنها تعدادی از مناطق مشکل را شناسایی کردند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750187.mp3"}]'::jsonb,2),
('6a25cf5d-d133-5feb-9b02-9a1dd70de40d','820145c6-245e-5def-8ea6-f9057328ab32',3,null,null,'spoken & written','if a particular thing identifies someone or something, it makes them easy to recognize',null,null,'اگر یک چیز خاص کسی یا چیزی را شناسایی کند، تشخیص آن را آسان می کند','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"His accent identified him as a Frenchman.","translation":"لهجه‌اش او را یک فرانسوی می‌دانست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001398302.mp3"}]'::jsonb,1),
('c6e1262c-1449-5a09-8cf9-3764f15f1cae','33f93b47-8474-59e6-95b4-661e0b090399',1,null,null,'spoken & written','someone’s identity is their name or who they are','[ countable, uncountable ]',null,'هویت؛ همانندی (ریاضی)؛ هویت (دارایی)','{}'::text[],'{}'::text[],array['somebody’s real/true identity The true identity of the author was not revealed until 100 years later.','a new/different identity He avoided arrest by adopting a new identity.','a false identity (= when someone pretends to be another person ) He used a fake passport to assume a false identity.','find out/discover somebody’s identity The police have yet to discover the victim’s identity.','know somebody’s identity He wanted to know the identity of his real father.','hide/conceal somebody’s identity She used a false name to conceal her identity.','reveal/disclose somebody’s identity (= show or say who a person is ) The company did not reveal the identity of the prospective buyer.','give away somebody’s identity (= accidentally reveal it ) The thief gave away his identity by mistake.','protect somebody’s identity (= make sure no one finds out who someone is ) Journalists frequently protect the identity of confidential sources.','adopt/assume an identity (= give yourself a new identity ) She assumed a false identity and went to live in South America.','identity card/papers/documents (= documents that show who you are ) Each member of staff is issued with an identity card.','an identity parade British English (= when someone looks at a line of people to see if they recognize a criminal ) The victim identified her attacker from an identity parade.','identity theft/fraud (= the crime of stealing another person''s personal details in order to pretend to be that person ) Identity theft is becoming more and more common because of the Internet.','proof of identity (= something that proves you are who you say you are ) You’ll need proof of identity, such as a driving licence.','a case of mistaken identity (= when people think that someone is a different person, especially with the result that they are accused of something that they did not do ) The defendant claimed he’d been arrested in a case of mistaken identity.']::text[],'[{"sentence":"The identity of the killer is still unknown.","translation":"هویت قاتل هنوز مشخص نیست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001972649.mp3"}]'::jsonb,1),
('16135775-e257-5dd9-bb65-81c9e8f7997b','33f93b47-8474-59e6-95b4-661e0b090399',2,null,null,'spoken & written','the qualities and attitudes that a person or group of people have, that make them different from other people','[ uncountable ]',null,'ویژگی ها و نگرش هایی که یک فرد یا گروهی از مردم دارند و آنها را از سایر افراد متمایز می کند','{}'::text[],'{}'::text[],array['somebody’s real/true identity The true identity of the author was not revealed until 100 years later.','a new/different identity He avoided arrest by adopting a new identity.','a false identity (= when someone pretends to be another person ) He used a fake passport to assume a false identity.','find out/discover somebody’s identity The police have yet to discover the victim’s identity.','know somebody’s identity He wanted to know the identity of his real father.','hide/conceal somebody’s identity She used a false name to conceal her identity.','reveal/disclose somebody’s identity (= show or say who a person is ) The company did not reveal the identity of the prospective buyer.','give away somebody’s identity (= accidentally reveal it ) The thief gave away his identity by mistake.','protect somebody’s identity (= make sure no one finds out who someone is ) Journalists frequently protect the identity of confidential sources.','adopt/assume an identity (= give yourself a new identity ) She assumed a false identity and went to live in South America.','identity card/papers/documents (= documents that show who you are ) Each member of staff is issued with an identity card.','an identity parade British English (= when someone looks at a line of people to see if they recognize a criminal ) The victim identified her attacker from an identity parade.','identity theft/fraud (= the crime of stealing another person''s personal details in order to pretend to be that person ) Identity theft is becoming more and more common because of the Internet.','proof of identity (= something that proves you are who you say you are ) You’ll need proof of identity, such as a driving licence.','a case of mistaken identity (= when people think that someone is a different person, especially with the result that they are accused of something that they did not do ) The defendant claimed he’d been arrested in a case of mistaken identity.']::text[],'[{"sentence":"Children need continuity, security, and a sense of identity .","translation":"کودکان به تداوم، امنیت و احساس هویت نیاز دارند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750211.mp3"},{"sentence":"Travelling alone can lead to a loss of identity .","translation":"سفر به تنهایی می تواند منجر به از دست دادن هویت شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750215.mp3"},{"sentence":"Our strong sense of national identity has been shaped by our history.","translation":"حس قوی هویت ملی ما توسط تاریخ ما شکل گرفته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750219.mp3"},{"sentence":"My father experienced an identity crisis in middle age.","translation":"پدرم در میانسالی دچار بحران هویت شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001750220.mp3"}]'::jsonb,4),
('40a79f23-0818-5d28-991c-cf0c65e99d3c','33f93b47-8474-59e6-95b4-661e0b090399',3,null,null,'formal','exact similarity between two things','[ uncountable ]',null,'شباهت دقیق بین دو چیز','{}'::text[],'{}'::text[],array['somebody’s real/true identity The true identity of the author was not revealed until 100 years later.','a new/different identity He avoided arrest by adopting a new identity.','a false identity (= when someone pretends to be another person ) He used a fake passport to assume a false identity.','find out/discover somebody’s identity The police have yet to discover the victim’s identity.','know somebody’s identity He wanted to know the identity of his real father.','hide/conceal somebody’s identity She used a false name to conceal her identity.','reveal/disclose somebody’s identity (= show or say who a person is ) The company did not reveal the identity of the prospective buyer.','give away somebody’s identity (= accidentally reveal it ) The thief gave away his identity by mistake.','protect somebody’s identity (= make sure no one finds out who someone is ) Journalists frequently protect the identity of confidential sources.','adopt/assume an identity (= give yourself a new identity ) She assumed a false identity and went to live in South America.','identity card/papers/documents (= documents that show who you are ) Each member of staff is issued with an identity card.','an identity parade British English (= when someone looks at a line of people to see if they recognize a criminal ) The victim identified her attacker from an identity parade.','identity theft/fraud (= the crime of stealing another person''s personal details in order to pretend to be that person ) Identity theft is becoming more and more common because of the Internet.','proof of identity (= something that proves you are who you say you are ) You’ll need proof of identity, such as a driving licence.','a case of mistaken identity (= when people think that someone is a different person, especially with the result that they are accused of something that they did not do ) The defendant claimed he’d been arrested in a case of mistaken identity.']::text[],'[]'::jsonb,0),
('c4b11e0a-7678-5d26-a36e-5ab9069be9bb','d896bac6-5d18-5d75-bd8e-be97ad873977',1,null,null,'spoken & written','an event, especially one that is unusual , important, or violent',null,null,'رخداد، حادثه؛ پیشامد (ناهماهنگ)','{}'::text[],'{}'::text[],array['a serious incident The road is closed following a serious incident earlier today.','a major incident (= very serious ) The most recent major incident was an explosion at an oil refinery.','a small/minor incident An apparently minor incident sparked off rioting.','the whole incident The whole incident was caught on CCTV.','a separate incident Young men were killed in two separate incidents on the same day.','a related incident (= connected to another incident ) The report describes a number of related incidents.','an isolated incident (= one that happens on its own, not together with others ) Luckily the attack turned out to be an isolated incident.','the latest incident (= the most recent one ) In the latest incident a post office was broken into.','a dramatic incident (= unexpected and exciting ) Viewers watched the dramatic incident on the television news.','a violent incident There have been several violent incidents at football matches recently.','a tragic incident (= one that involves someone’s death ) Andrew’s father was lost at sea in this tragic incident.','an unfortunate incident (= involving an accident or argument ) Disciplinary action may be taken over this unfortunate incident.','an embarrassing incident He left after an embarrassing incident in the bar.','a strange/unusual incident Any unusual incidents should be reported to the police.','a shooting/stabbing incident (= when someone is shot or stabbed ) Two men died today in a shooting incident.','an incident happens The incident happened as Mrs Edwards was walking her dog.','an incident occurs formal: The tragic incident occurred just after midnight.','cause an incident His carelessness caused a major incident.','provoke/spark off an incident (= cause it to happen suddenly ) It is claimed that the police provoked the incident.','be involved in an incident All those involved in the incident were sacked.','deal with/handle an incident The police were criticized for the way in which they handled the incident.','describe an incident Police asked the victim to describe the incident.']::text[],'[{"sentence":"Am I at risk because of some incident in my sexual past?","translation":"آیا من به دلیل اتفاقاتی در گذشته جنسی خود در معرض خطر هستم؟","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726451.mp3"},{"sentence":"Roads were sealed off because of a major incident.","translation":"جاده ها به دلیل یک حادثه بزرگ مسدود شد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/ldoce5_exa000837.mp3"},{"sentence":"The plane landed without incident.","translation":"هواپیما بدون حادثه فرود آمد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726457.mp3"},{"sentence":"Am I at risk because of something that happened in my past?","translation":"آیا من به خاطر اتفاقی که در گذشته ام رخ داده در معرض خطر هستم؟","audio_url":null}]'::jsonb,4),
('46d92fa7-b416-5bad-b919-1324078b8a58','d896bac6-5d18-5d75-bd8e-be97ad873977',2,null,null,'spoken & written','a serious disagreement between two countries',null,null,'اختلاف جدی بین دو کشور','{}'::text[],'{}'::text[],array['a serious incident The road is closed following a serious incident earlier today.','a major incident (= very serious ) The most recent major incident was an explosion at an oil refinery.','a small/minor incident An apparently minor incident sparked off rioting.','the whole incident The whole incident was caught on CCTV.','a separate incident Young men were killed in two separate incidents on the same day.','a related incident (= connected to another incident ) The report describes a number of related incidents.','an isolated incident (= one that happens on its own, not together with others ) Luckily the attack turned out to be an isolated incident.','the latest incident (= the most recent one ) In the latest incident a post office was broken into.','a dramatic incident (= unexpected and exciting ) Viewers watched the dramatic incident on the television news.','a violent incident There have been several violent incidents at football matches recently.','a tragic incident (= one that involves someone’s death ) Andrew’s father was lost at sea in this tragic incident.','an unfortunate incident (= involving an accident or argument ) Disciplinary action may be taken over this unfortunate incident.','an embarrassing incident He left after an embarrassing incident in the bar.','a strange/unusual incident Any unusual incidents should be reported to the police.','a shooting/stabbing incident (= when someone is shot or stabbed ) Two men died today in a shooting incident.','an incident happens The incident happened as Mrs Edwards was walking her dog.','an incident occurs formal: The tragic incident occurred just after midnight.','cause an incident His carelessness caused a major incident.','provoke/spark off an incident (= cause it to happen suddenly ) It is claimed that the police provoked the incident.','be involved in an incident All those involved in the incident were sacked.','deal with/handle an incident The police were criticized for the way in which they handled the incident.','describe an incident Police asked the victim to describe the incident.']::text[],'[{"sentence":"You could have caused a major diplomatic incident .","translation":"شما می توانستید یک حادثه دیپلماتیک بزرگ ایجاد کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001370237.mp3"}]'::jsonb,1),
('c5bbe419-8eb2-504b-be70-690b93e502b8','2ab13f91-1999-597b-8660-2e0cf7685e44',1,null,null,'spoken & written','if you increase something, or if it increases, it becomes bigger in amount, number, or degree','[ intransitive, transitive ]',null,'افزایش دادن؛ زیاد شدن؛ بالا رفتن (قیمت)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The population increased dramatically in the first half of the century.","translation":"جمعیت در نیمه اول قرن به طور چشمگیری افزایش یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001373524.mp3"},{"sentence":"political tensions that might increase the likelihood of war","translation":"تنش های سیاسی که ممکن است احتمال جنگ را افزایش دهد","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726664.mp3"},{"sentence":"Visits to the site have increased threefold since May.","translation":"بازدید از این سایت از ماه می سه برابر شده است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001373525.mp3"},{"sentence":"Investments are certain to increase in value.","translation":"ارزش سرمایه گذاری قطعا افزایش می یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001373528.mp3"},{"sentence":"Food prices increased by 10% in less than a year.","translation":"قیمت مواد غذایی در کمتر از یک سال 10 درصد افزایش یافت.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001373531.mp3"},{"sentence":"The salary is £18,600 a year, increasing to £23,000.","translation":"حقوق 18600 پوند در سال است که به 23000 پوند افزایش می یابد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001726667.mp3"},{"sentence":"The population has gone up a lot.","translation":"جمعیت خیلی زیاد شده","audio_url":null},{"sentence":"Her investments all went up in value.","translation":"ارزش سرمایه گذاری های او همگی افزایش یافت.","audio_url":null}]'::jsonb,8),
('d86e250f-cffb-55bf-b5ab-fd5800eb334e','b163c687-3f59-593d-a48d-cc2953273779',1,null,null,'spoken & written','a rise in amount, number, or degree',null,null,'افزایش، بالا رفتن (مقدار)','{}'::text[],'{}'::text[],array['big/large The company has announced a big increase in its profits for last year.','slight/small Doctors have reported a slight increase in the number of deaths caused by the disease. The temperature increase was quite small.','great (= big ) There has been a great increase in air traffic in the last twenty years.','huge/massive (= very big ) There was a huge increase in emigration after the war.','substantial/considerable formal (= quite big ) He negotiated a substantial increase in pay for the workers.','significant/marked (= definite and noticeable ) Over the last few years, there has been a marked increase in tourism to developing countries.','dramatic/sharp (= large and sudden ) What has led to this dramatic increase in prices?','rapid (= happening quickly ) Recently there has been a rapid increase in fish farming.','modest (= small ) The figures reveal a modest increase in the birth rate.','gradual (= happening slowly ) Her temperature chart showed a gradual increase over the preceding six hours.','steady (= happening slowly but continuously ) The university has benefited from a steady increase in student numbers.','a threefold/fourfold/fivefold etc increase (= an increase by three, four etc times ) The figures show a threefold increase in incidents of car theft.','a 10%/50% etc increase A 5% increase in petrol prices is predicted.','an annual increase The company reported a 10% increase in pre-tax profits.','lead to an increase They argue that the abolition of the death penalty has led to an increase in the number of murders.','cause/bring about an increase The heat wave brought about a massive increase in water consumption.','a price increase We expect a price increase of 1.4% this year.','a fare increase The airline instituted a 10% fare increase.','a wage/pay/salary increase Canadian workers received a 5.4% wage increase.','a tax increase The government had no choice but to impose a tax increase.','be on the increase (= be increasing ) Knife attacks are on the increase.','the rate of increase The rate of increase in the number of violent crimes is much higher than under the previous government.']::text[],'[{"sentence":"an increase in the crime rate","translation":"افزایش نرخ جرم و جنایت","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973159.mp3"},{"sentence":"Recent tax increases have affected the poor more than the rich.","translation":"افزایش مالیات های اخیر بیشتر بر فقرا تاثیر گذاشته تا ثروتمندان.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973160.mp3"},{"sentence":"the dramatic increase in the population aged over 65","translation":"افزایش چشمگیر جمعیت بالای 65 سال","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973164.mp3"},{"sentence":"There has been a marked increase in the use of firearms.","translation":"استفاده از سلاح گرم افزایش قابل توجهی داشته است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973168.mp3"},{"sentence":"Cases of tuberculosis are on the increase .","translation":"موارد سل در حال افزایش است.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001973172.mp3"}]'::jsonb,5),
('a044b1be-ea5c-5b98-b29e-f55ad57ce0ac','23a9fcc0-7522-53f0-99c2-3f4a7e5529be',1,null,null,'spoken & written','to show that a particular situation exists , or that something is likely to be true','[ transitive ]',null,'نشان دادن؛ حاکی بودن؛ نشان دادن (چراغ)','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Research indicates that over 81% of teachers are dissatisfied with their salary.","translation":"تحقیقات نشان می دهد که بیش از 81 درصد معلمان از حقوق خود ناراضی هستند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376798.mp3"},{"sentence":"Long skid marks on the pavement indicated the driver had attempted to brake.","translation":"لغزش های طولانی روی پیاده رو نشان می دهد که راننده سعی کرده است ترمز کند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733712.mp3"},{"sentence":"The study indicates a connection between poverty and crime.","translation":"این مطالعه ارتباط بین فقر و جرم را نشان می دهد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376795.mp3"}]'::jsonb,3),
('42fb4139-611d-58bf-a5fe-8e96d1bd8ba6','23a9fcc0-7522-53f0-99c2-3f4a7e5529be',2,null,null,'spoken & written','to say or do something to make your wishes , intentions etc clear','[ transitive ]',null,'گفتن یا انجام کاری برای روشن کردن خواسته ها، نیات و غیره','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"The Russians have already indicated their willingness to cooperate.","translation":"روس ها قبلاً تمایل خود را برای همکاری نشان داده اند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376810.mp3"},{"sentence":"Professor Johnson has indicated his intention to retire at the end of next year.","translation":"پروفسور جانسون اعلام کرده است که قصد دارد در پایان سال آینده بازنشسته شود.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733713.mp3"},{"sentence":"Ralph patted the sofa to indicate that she should join him.","translation":"رالف به مبل دست زد تا نشان دهد که باید به او بپیوندد.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733716.mp3"},{"sentence":"Please indicate your preference on the booking form.","translation":"لطفا اولویت خود را در فرم رزرو اعلام کنید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733717.mp3"}]'::jsonb,4),
('7f09f044-fbe7-5b4d-8088-937a83cf22b0','23a9fcc0-7522-53f0-99c2-3f4a7e5529be',3,null,null,'spoken & written','to direct someone’s attention to something or someone, for example by pointing','[ transitive ]',null,'جلب توجه کسی به چیزی یا کسی، مثلاً با اشاره کردن','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"‘That’s her, ’ said Toby, indicating a girl on the other side of the room.","translation":"توبی با اشاره به دختری در طرف دیگر اتاق گفت: «این اوست.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001733718.mp3"}]'::jsonb,1),
('abef7f25-f315-5a18-be37-c0c220a3a5f3','23a9fcc0-7522-53f0-99c2-3f4a7e5529be',4,null,null,'spoken & written','to represent something','[ transitive ]',null,'نشان دادن چیزی','{}'::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Sales targets are indicated on the graph by a vertical dotted line.","translation":"اهداف فروش در نمودار با یک خط نقطه چین عمودی نشان داده می شوند.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376822.mp3"}]'::jsonb,1),
('e051486b-d522-56b3-a0d1-9705c90d773c','23a9fcc0-7522-53f0-99c2-3f4a7e5529be',5,null,null,'spoken & written','to show the direction in which you intend to turn in a vehicle , using lights or your hands','[ intransitive, transitive ]',null,'برای نشان دادن جهتی که قصد دارید در وسیله نقلیه بپیچید، با استفاده از چراغ ها یا دستان خود',array['signal']::text[],'{}'::text[],'{}'::text[],'[{"sentence":"Don’t forget to indicate before you pull out.","translation":"فراموش نکنید که قبل از بیرون کشیدن نشان دهید.","audio_url":"https://www.ldoceonline.com/media/english/exaProns/p008-001376830.mp3"}]'::jsonb,1)
